/* Canada Citizenship Practice — expanded question bank
   Based on the official "Discover Canada" study guide.
   UNOFFICIAL practice questions. Review for accuracy before launch.
   Format: { q, options:[...], answer:index, explain, chapter }
*/
const CITIZENSHIP_QUESTIONS = [
  // ---------- About the test ----------
  { q:"How many correct answers do you need to pass the real Canadian citizenship test?", options:["10 out of 20","15 out of 20","18 out of 20","20 out of 20"], answer:1, explain:"The real test has 20 questions and you must get at least 15 correct (75%) to pass.", chapter:"About the Test" },
  { q:"How much time do you have to complete the real citizenship test?", options:["45 minutes","20 minutes","No time limit","10 minutes"], answer:0, explain:"You are given 45 minutes to answer the 20 questions — a little over two minutes each. Older guides say 30 minutes; that figure is out of date.", chapter:"About the Test" },
  { q:"Which official guide should you study to prepare for the citizenship test?", options:["The Citizen's Almanac","Discover Canada","The Canada Handbook","A Guide to Voting"],answer:1, explain:"The official study guide is called 'Discover Canada: The Rights and Responsibilities of Citizenship'.", chapter:"About the Test" },

  // ---------- Rights and Responsibilities ----------
  { q:"Which document sets out the rights and freedoms of people in Canada?", options:["The Bill of Sale","The Magna Carta","The Canadian Charter of Rights and Freedoms","The Declaration of Independence"],answer:2, explain:"The Canadian Charter of Rights and Freedoms (1982) sets out our basic rights and freedoms.", chapter:"Rights and Responsibilities" },
  { q:"In what year did the Canadian Charter of Rights and Freedoms become part of the Constitution?", options:["1867","1931","1982","2001"], answer:2, explain:"The Charter became part of the Constitution in 1982.", chapter:"Rights and Responsibilities" },
  { q:"Which of these is one of the fundamental freedoms in the Charter?", options:["Free housing","Free education for life","Free health care for tourists","Freedom of speech and expression"],answer:3, explain:"Freedom of thought, belief, opinion and expression is a fundamental freedom in the Charter.", chapter:"Rights and Responsibilities" },
  { q:"Freedom of conscience and religion means Canadians can…", options:["Practise any religion or none at all","Never discuss religion","Be forced to attend church","Only follow one national religion"],answer:0, explain:"Freedom of conscience and religion lets people follow any religion or none.", chapter:"Rights and Responsibilities" },
  { q:"Which of the following is a RESPONSIBILITY of Canadian citizenship?", options:["Joining the army","Obeying the law","Owning a home","Speaking French"],answer:1, explain:"Obeying the law is a key responsibility of citizenship.", chapter:"Rights and Responsibilities" },
  { q:"What does the Charter say about the existing rights of the Aboriginal peoples of Canada?", options:["They apply only on reserves","They end once a treaty is signed","Nothing in the Charter takes away from them","They are replaced by the Charter"], answer:2, explain:"The Charter protects Aboriginal and treaty rights instead of reducing them. Section 35 of the Constitution Act, 1982 recognizes and affirms those rights.", chapter:"Rights and Responsibilities" },
  { q:"Which is a responsibility that helps your community and country?", options:["Avoiding all taxes","Ignoring elections","Never working","Volunteering and helping others"],answer:3, explain:"Helping others in the community is an important responsibility.", chapter:"Rights and Responsibilities" },
  { q:"Where do Canada's laws and rights come from, in part?", options:["English common law and French civil law","Only the United States","Only the King","Only the provinces"], answer:0, explain:"Canadian law is rooted in English common law and, in Quebec, French civil law.", chapter:"Rights and Responsibilities" },
  { q:"The right of 'habeas corpus' means…", options:["The right to keep property","The right to challenge unlawful detention","The right to vote twice","The right to free speech only"], answer:1, explain:"Habeas corpus is the right to challenge unlawful detention by the state; it comes from English law.", chapter:"Rights and Responsibilities" },
  { q:"Which travel document may only a Canadian citizen apply for?", options:["A Canadian passport","A social insurance card","A driver's licence","A permanent resident card"], answer:0, explain:"Permanent residents carry a PR card, but a Canadian passport is a right that comes with citizenship. Citizens may also live outside Canada without losing their status.", chapter:"Rights and Responsibilities" },
  { q:"Men and women are equal under Canadian law. How does that law treat spousal abuse and forced marriage?", options:["They are private family matters","They are crimes","They are allowed if the family agrees","They are left to religious leaders"], answer:1, explain:"Canadian law protects everyone from violence, whatever reason is given for it. Police, courts and shelters treat these acts as crimes and help the people harmed.", chapter:"Rights and Responsibilities" },
  { q:"Paying taxes is…", options:["A responsibility of everyone in Canada","Only for citizens over 65","Only for business owners","Optional"],answer:0, explain:"Paying taxes is a responsibility for everyone who earns money in Canada.", chapter:"Rights and Responsibilities" },
  { q:"Which right do Canadian citizens have that some non-citizens do not?", options:["The right to an education","The right to vote in elections","The right to drive","The right to work"],answer:1, explain:"Only Canadian citizens can vote and run in federal and provincial elections.", chapter:"Rights and Responsibilities" },
  { q:"Equality rights in the Charter mean everyone is…", options:["Given free land","Required to be the same religion","Equal under the law","Given the same salary"],answer:2, explain:"Equality rights mean every person is equal under the law, regardless of background.", chapter:"Rights and Responsibilities" },

  // ---------- Who We Are / Aboriginal peoples ----------
  { q:"Which three groups are the Aboriginal (Indigenous) peoples of Canada?", options:["English, French, and Irish","North, South, and Central","Farmers, fishers, and miners","First Nations, Métis, and Inuit"],answer:3, explain:"The Aboriginal peoples of Canada are the First Nations, the Métis, and the Inuit.", chapter:"Canada's History" },
  { q:"The Inuit live mostly in which part of Canada?", options:["The Arctic (North)","The Prairies","The West Coast","Southern Ontario"], answer:0, explain:"The Inuit live mostly in the Arctic, in Canada's far North.", chapter:"Canada's History" },
  { q:"The Métis are a people of mixed…", options:["French and Spanish ancestry","Aboriginal and European ancestry","Asian and African ancestry","British and American ancestry"],answer:1, explain:"The Métis are a distinct people of mixed Aboriginal and European (mainly French) ancestry.", chapter:"Canada's History" },
  { q:"Between 1871 and 1921, what did the Crown sign with First Nations across the Prairies and the North?", options:["The Treaty of Paris","The numbered treaties","The Quebec Act","The Statute of Westminster"], answer:1, explain:"Eleven numbered treaties set out promises about land, payments, schooling and hunting rights. They still shape the relationship between First Nations and governments today.", chapter:"Canada's History" },
  { q:"The word 'Canada' comes from an Aboriginal word 'kanata' meaning…", options:["River","Mountain","Snow","Village"],answer:3, explain:"'Kanata' is a Huron-Iroquois word meaning 'village' or 'settlement'.", chapter:"Canada's History" },

  // ---------- Canada's History (early to 1800s) ----------
  { q:"Which European explorers first reached Canada around 1,000 years ago?", options:["The Vikings (Norse)","The Spanish","The Portuguese","The Dutch"], answer:0, explain:"Norse (Viking) explorers reached the northern tip of Newfoundland about 1,000 years ago.", chapter:"Canada's History" },
  { q:"Who claimed land for France and helped name 'Canada' in the 1530s?", options:["Christopher Columbus","Jacques Cartier","John Cabot","Samuel de Champlain"],answer:1, explain:"Jacques Cartier explored the St. Lawrence in the 1530s and the name 'Canada' came into use.", chapter:"Canada's History" },
  { q:"Who founded Quebec City in 1608 and is called the 'Father of New France'?", options:["John A. Macdonald","Louis Riel","Samuel de Champlain","Jacques Cartier"],answer:2, explain:"Samuel de Champlain founded Quebec City in 1608.", chapter:"Canada's History" },
  { q:"In the 1700s, the French colony in Canada was called…", options:["Upper Canada","British Columbia","New England","New France"],answer:3, explain:"The French colony along the St. Lawrence was called New France.", chapter:"Canada's History" },
  { q:"Which animal's fur drove much of Canada's early economy?", options:["Beaver","Fox","Bear","Deer"], answer:0, explain:"The beaver fur trade was one of Canada's earliest and most important industries.", chapter:"Canada's Economy" },
  { q:"The 1759 Battle of the Plains of Abraham was fought near which city?", options:["Toronto","Quebec City","Halifax","Montreal"],answer:1, explain:"The battle was fought near Quebec City; Britain defeated France there in 1759.", chapter:"Canada's History" },
  { q:"After Britain defeated France, the 1763 Treaty of Paris gave Canada to…", options:["The United States","The Netherlands","Britain","Spain"],answer:2, explain:"The 1763 Treaty of Paris gave New France to Britain.", chapter:"Canada's History" },
  { q:"Which 1774 law recognized the religion and language of the French in Canada?", options:["The Constitution Act","The Charter","The Indian Act","The Quebec Act"],answer:3, explain:"The Quebec Act of 1774 allowed religious freedom for Catholics and kept French civil law.", chapter:"Canada's History" },
  { q:"The Loyalists who came to Canada after 1776 were loyal to…", options:["The British Crown","France","Spain","The United States"], answer:0, explain:"United Empire Loyalists left the United States to stay loyal to the British Crown.", chapter:"Canada's History" },
  { q:"In the War of 1812, who invaded Canada but was defeated?", options:["Russia","The United States","France","Britain"],answer:1, explain:"The United States invaded Canada during the War of 1812 but the invasion was defeated.", chapter:"Canada's History" },
  { q:"Which heroine warned of an American attack during the War of 1812?", options:["Emily Carr","Agnes Macphail","Laura Secord","Nellie McClung"],answer:2, explain:"Laura Secord walked 30 km to warn of an American attack in 1813.", chapter:"Canada's History" },
  { q:"The Hudson's Bay Company, founded in 1670, traded mainly in…", options:["Gold","Spices","Cars","Furs"],answer:3, explain:"The Hudson's Bay Company was a major fur-trading company.", chapter:"Canada's Economy" },
  { q:"'Responsible government' means the government must have the support of…", options:["The elected assembly","The King alone","The army","The courts"], answer:0, explain:"Responsible government means ministers must have the confidence of the elected assembly.", chapter:"How Canadians Govern Themselves" },

  // ---------- Confederation ----------
  { q:"On what date did Canada become a country (Confederation)?", options:["November 11, 1918","July 1, 1867","July 4, 1776","January 1, 1900"],answer:1, explain:"Canada became a country on July 1, 1867. We celebrate this as Canada Day.", chapter:"Canada's History" },
  { q:"How many provinces first joined Confederation in 1867?", options:["Eight","Ten","Four","Six"],answer:2, explain:"Ontario, Quebec, Nova Scotia, and New Brunswick joined first in 1867.", chapter:"Canada's History" },
  { q:"Who was Canada's first Prime Minister?", options:["Sir Wilfrid Laurier","Sir George-Étienne Cartier","Louis Riel","Sir John A. Macdonald"],answer:3, explain:"Sir John A. Macdonald was Canada's first Prime Minister. His image is on the $10 bill.", chapter:"Canada's History" },
  { q:"The leaders who worked to create Canada in 1867 are called the…", options:["Fathers of Confederation","Founding Kings","First Ministers","Loyalists"], answer:0, explain:"The Fathers of Confederation created the Dominion of Canada in 1867.", chapter:"Canada's History" },
  { q:"The law that created Canada in 1867 was called the…", options:["Indian Act","British North America Act (Constitution Act, 1867)","Charter of Rights","Quebec Act"],answer:1, explain:"The British North America Act (now the Constitution Act, 1867) created Canada.", chapter:"How Canadians Govern Themselves" },
  { q:"Which railway, finished in 1885, connected Canada from east to west?", options:["The Grand Trunk Road","The Arctic Line","The Canadian Pacific Railway","The Trans-Canada Highway"],answer:2, explain:"The Canadian Pacific Railway was completed in 1885, uniting the country.", chapter:"Canada's History" },
  { q:"Who led the Métis in the Red River and North-West resistances?", options:["Terry Fox","Tecumseh","Sir John A. Macdonald","Louis Riel"],answer:3, explain:"Louis Riel led the Métis and helped bring Manitoba into Confederation.", chapter:"Canada's History" },
  { q:"What was the last province to join Canada, in 1949?", options:["Newfoundland and Labrador","Manitoba","British Columbia","Alberta"],answer:0, explain:"Newfoundland and Labrador was the last province to join Canada, in 1949.", chapter:"Canada's History" },
  { q:"Nunavut became Canada's newest territory in which year?", options:["1949","1982","1999","2005"], answer:2, explain:"Nunavut was created as a territory in 1999.", chapter:"Canada's Regions" },

  // ---------- 1900s history ----------
  { q:"Canadian troops famously captured which ridge in 1917 during World War I?", options:["Gallipoli","Vimy Ridge","Juno Beach","Normandy"],answer:1, explain:"Canadians captured Vimy Ridge in 1917 — a proud national moment.", chapter:"Canada's History" },
  { q:"Which Canadian doctor wrote the famous poem 'In Flanders Fields'?", options:["Norman Bethune","Alexander Fleming","John McCrae","Frederick Banting"],answer:2, explain:"Lieutenant-Colonel John McCrae wrote 'In Flanders Fields' during the First World War.", chapter:"Canada's History" },
  { q:"On which beach did Canadian soldiers land on D-Day in 1944?", options:["Vimy Beach","Dieppe Beach","Gold Beach","Juno Beach"],answer:3, explain:"Canadian troops landed on Juno Beach in the D-Day invasion of June 6, 1944.", chapter:"Canada's History" },
  { q:"In which year did most Canadian women gain the right to vote federally?", options:["1867","1918","1945","1982"], answer:1, explain:"Most women gained the right to vote in federal elections in 1918.", chapter:"Canada's History" },
  { q:"The 'Famous Five' women helped win the 1929 ruling that women are legally…", options:["'Persons'","Voters","Citizens","Equal in pay"], answer:0, explain:"The 'Persons Case' of 1929 confirmed that women are 'persons' who can serve in the Senate.", chapter:"Canada's History" },
  { q:"In what year was the current red-and-white maple leaf flag first raised?", options:["1867","1931","1965","1982"], answer:2, explain:"The maple leaf flag was first raised on February 15, 1965.", chapter:"Canadian Symbols" },
  { q:"Terry Fox's 'Marathon of Hope' to fight cancer took place in which year?", options:["1965","1980","1995","2005"], answer:1, explain:"Terry Fox ran his Marathon of Hope in 1980 and became a national hero.", chapter:"Modern Canada" },
  { q:"Which Canadian won the Nobel Peace Prize for helping create UN peacekeeping?", options:["John Diefenbaker","Lester B. Pearson","Pierre Trudeau","Tommy Douglas"],answer:1, explain:"Lester B. Pearson won the Nobel Peace Prize in 1957 and later became Prime Minister.", chapter:"Modern Canada" },
  { q:"Insulin, used to treat diabetes, was co-discovered by which Canadian?", options:["Terry Fox","Marshall McLuhan","Sir Frederick Banting","Alexander Graham Bell"],answer:2, explain:"Sir Frederick Banting and Charles Best discovered insulin in the 1920s.", chapter:"Modern Canada" },
  { q:"Who is often called the 'father of medicare' (public health care) in Canada?", options:["John A. Macdonald","Wilfrid Laurier","Louis Riel","Tommy Douglas"],answer:3, explain:"Tommy Douglas is remembered as the father of Canada's public health care system.", chapter:"Canada's Economy" },

  // ---------- How Canadians Govern Themselves ----------
  { q:"What type of government does Canada have?", options:["A federal state, parliamentary democracy and constitutional monarchy","A republic","A dictatorship","A city-state"], answer:0, explain:"Canada is a federal state, a parliamentary democracy, and a constitutional monarchy.", chapter:"How Canadians Govern Themselves" },
  { q:"Who is Canada's Head of State?", options:["The Governor General","The Sovereign (currently King Charles III)","The President","The Prime Minister"],answer:1, explain:"Canada's Head of State is the Sovereign — currently King Charles III.", chapter:"How Canadians Govern Themselves" },
  { q:"Who is Canada's Head of Government?", options:["The Chief Justice","The King","The Prime Minister","The Governor General"],answer:2, explain:"The Prime Minister is the Head of Government and runs the country day to day.", chapter:"How Canadians Govern Themselves" },
  { q:"Who represents the Sovereign in Canada at the federal level?", options:["The Mayor","The Chief Justice","The Prime Minister","The Governor General"],answer:3, explain:"The Governor General represents the Sovereign at the federal level.", chapter:"How Canadians Govern Themselves" },
  { q:"Who represents the Sovereign in each province?", options:["The Lieutenant Governor","The Mayor","The Premier","The Senator"], answer:0, explain:"A Lieutenant Governor represents the Sovereign in each province.", chapter:"How Canadians Govern Themselves" },
  { q:"What are the three parts of Parliament?", options:["The Army, Navy, and Air Force","The Sovereign, the Senate, and the House of Commons","The Prime Minister, courts, and police","The provinces, cities, and towns"],answer:1, explain:"Parliament has three parts: the Sovereign, the Senate, and the House of Commons.", chapter:"How Canadians Govern Themselves" },
  { q:"Members of which house of Parliament are ELECTED by the people?", options:["The Cabinet","The Supreme Court","The House of Commons","The Senate"],answer:2, explain:"Members of Parliament (MPs) in the House of Commons are elected by voters.", chapter:"How Canadians Govern Themselves" },
  { q:"How do Senators get their positions?", options:["They are elected","They inherit them","They are chosen by lottery","They are appointed"],answer:3, explain:"Senators are appointed (on the advice of the Prime Minister), not elected.", chapter:"How Canadians Govern Themselves" },
  { q:"What normally happens when the government loses a confidence vote in the House of Commons?", options:["Nothing changes","The Senate takes over","An election is usually called","The Governor General governs alone"], answer:2, explain:"A government must keep the confidence of the elected House. If it loses a budget vote or a confidence motion, the Prime Minister normally asks the Governor General to call an election.", chapter:"How Canadians Govern Themselves" },
  { q:"What is the Cabinet?", options:["The provincial premiers","Ministers chosen by the PM to run government departments","A group of judges","The Senate"],answer:1, explain:"Cabinet ministers are chosen by the Prime Minister and are usually MPs.", chapter:"How Canadians Govern Themselves" },
  { q:"How many levels of government does Canada have?", options:["Five","Two","Three","Four"],answer:2, explain:"Canada has three levels: federal, provincial/territorial, and municipal (local).", chapter:"How Canadians Govern Themselves" },
  { q:"Which level of government is responsible for national defence and citizenship?", options:["School boards","Municipal","Provincial","Federal"],answer:3, explain:"The federal government handles national defence, foreign policy, and citizenship.", chapter:"How Canadians Govern Themselves" },
  { q:"Which level of government is mainly responsible for education and health care?", options:["Provincial/territorial","Municipal","The Crown","Federal"],answer:0, explain:"Provinces and territories are mainly responsible for education and health care.", chapter:"How Canadians Govern Themselves" },
  { q:"Which is usually a responsibility of MUNICIPAL (local) government?", options:["Foreign treaties","Snow removal and recycling","National defence","Citizenship"],answer:1, explain:"Local governments handle services like snow removal, recycling, and local roads.", chapter:"How Canadians Govern Themselves" },
  { q:"For a bill to become law, it must pass the House of Commons, the Senate, and then receive…", options:["Approval from the U.S.","A newspaper announcement","Royal Assent from the Governor General","A public vote"],answer:2, explain:"After both houses pass a bill, the Governor General gives Royal Assent to make it law.", chapter:"How Canadians Govern Themselves" },
  { q:"The head of a provincial government is called the…", options:["President","Mayor","Governor","Premier"],answer:3, explain:"The Premier leads a provincial or territorial government.", chapter:"How Canadians Govern Themselves" },
  { q:"The head of a city or town government is usually called the…", options:["Mayor","Premier","Governor General","Senator"], answer:0, explain:"A Mayor leads a municipal (city or town) government.", chapter:"How Canadians Govern Themselves" },

  // ---------- Federal Elections ----------
  { q:"How often must a federal election be held (at the latest)?", options:["Every year","At least every four years","Every ten years","Only when the King decides"], answer:1, explain:"By law a federal election must be held at least every four years.", chapter:"Federal Elections" },
  { q:"How old must you be to vote in a Canadian federal election?", options:["16","18","19","21"], answer:1, explain:"You must be a Canadian citizen and at least 18 years old on voting day.", chapter:"Federal Elections" },
  { q:"Who do Canadians elect to represent them in the House of Commons?", options:["Mayors","Senators","Members of Parliament (MPs)","Judges"],answer:2, explain:"Voters elect Members of Parliament (MPs) to the House of Commons.", chapter:"Federal Elections" },
  { q:"The area represented by one Member of Parliament is called a…", options:["Province","Ward","County","Riding (electoral district)"],answer:3, explain:"A riding, or electoral district, is the area an MP represents.", chapter:"Federal Elections" },
  { q:"What are the three requirements to vote in a federal election?", options:["Be a citizen, be 18+, and be on the voters list","Own a home, pay taxes, and be married","Speak English, drive, and work","Be born in Canada, be 21, and vote before"], answer:0, explain:"You must be a Canadian citizen, at least 18, and on the voters list.", chapter:"Federal Elections" },
  { q:"In Canada, voting is done by…", options:["The King's choice","Secret ballot","Public show of hands","Phone call"],answer:1, explain:"Canadians vote by secret ballot, so no one can be forced to reveal their vote.", chapter:"Federal Elections" },
  { q:"After a federal election, who usually forms the government?", options:["The party with the most money","The Supreme Court","The party with the most seats in the House of Commons","The Senate"],answer:2, explain:"The party that wins the most seats in the House of Commons usually forms the government.", chapter:"Federal Elections" },
  { q:"Which independent agency runs federal elections in Canada?", options:["The RCMP","The Senate","Service Canada","Elections Canada"],answer:3, explain:"Elections Canada is the independent agency that runs federal elections.", chapter:"Federal Elections" },

  // ---------- The Justice System ----------
  { q:"What does the 'rule of law' mean?", options:["Everyone, including governments, must obey the law","Only citizens obey the law","The King is above the law","Police make the laws"], answer:0, explain:"The rule of law means everyone — even leaders — is under the same law.", chapter:"The Justice System" },
  { q:"What is the highest court in Canada?", options:["The Provincial Court","The Supreme Court of Canada","The House of Commons","The Senate"],answer:1, explain:"The Supreme Court of Canada is the highest court in the country.", chapter:"The Justice System" },
  { q:"In Canadian justice, a person charged with a crime is…", options:["Not allowed a lawyer","Judged by the King","Presumed innocent until proven guilty","Presumed guilty"],answer:2, explain:"You are presumed innocent until proven guilty, and have the right to a fair trial.", chapter:"The Justice System" },
  { q:"What is the name of Canada's national police force?", options:["The Canadian Guard","The National Police Service","The FBI","The Royal Canadian Mounted Police (RCMP)"],answer:3, explain:"The Royal Canadian Mounted Police (RCMP), the 'Mounties', is the national police force.", chapter:"The Justice System" },

  // ---------- Canadian Symbols ----------
  { q:"What is Canada's national winter sport?", options:["Ice hockey","Skiing","Snowboarding","Curling"],answer:0, explain:"Ice hockey is the national winter sport; lacrosse is the national summer sport.", chapter:"Canadian Symbols" },
  { q:"What is Canada's national summer sport?", options:["Soccer","Lacrosse","Cricket","Baseball"],answer:1, explain:"Lacrosse is Canada's national summer sport.", chapter:"Canadian Symbols" },
  { q:"What is the title of Canada's national anthem?", options:["God Save the King","The Maple Leaf Forever","O Canada","True North"], answer:2, explain:"'O Canada' became the official national anthem in 1980.", chapter:"Canadian Symbols" },
  { q:"What animal is an official emblem of Canada and appears on the nickel?", options:["The kangaroo","The lion","The eagle","The beaver"],answer:3, explain:"The beaver is an official emblem and appears on the five-cent coin.", chapter:"Canadian Symbols" },
  { q:"What colours is the Canadian flag?", options:["Red and white","Blue and white","Red, white, and blue","Green and gold"], answer:0, explain:"The flag is red and white with a single red maple leaf.", chapter:"Canadian Symbols" },
  { q:"What do we celebrate on July 1st?", options:["Remembrance Day","Canada Day","Victoria Day","Labour Day"], answer:1, explain:"July 1st is Canada Day, marking Confederation in 1867.", chapter:"Canadian Symbols" },
  { q:"What do we remember on November 11th (Remembrance Day)?", options:["The founding of Ottawa","The end of winter","The men and women who served and died for Canada","The first Prime Minister"],answer:2, explain:"On Remembrance Day we honour Canadians who served and died in wars. Many wear a poppy.", chapter:"Canadian Symbols" },
  { q:"The red flower worn on Remembrance Day is the…", options:["Tulip","Lily","Rose","Poppy"],answer:3, explain:"The red poppy honours those who died in war, inspired by 'In Flanders Fields'.", chapter:"Canadian Symbols" },
  { q:"Canada's motto, 'A Mari Usque Ad Mare', means…", options:["From Sea to Sea","Peace and Order","True North","Strong and Free"], answer:0, explain:"The motto means 'From Sea to Sea'.", chapter:"Canadian Symbols" },
  { q:"Which tower is a famous part of the Parliament Buildings in Ottawa?", options:["The Eiffel Tower","The Peace Tower","The CN Tower","The Calgary Tower"],answer:1, explain:"The Peace Tower is a landmark of the Parliament Buildings in Ottawa.", chapter:"Canadian Symbols" },
  { q:"The fleur-de-lys is a traditional symbol of…", options:["The Prairies","The Arctic","French Canada / Quebec","British Columbia"],answer:2, explain:"The fleur-de-lys is a symbol of French heritage and appears on Quebec's flag.", chapter:"Canadian Symbols" },
  { q:"The maple leaf is a symbol of Canada. Where does it appear?", options:["Only on the flag","Nowhere official","Only in Quebec","On the flag, coins, and coat of arms"],answer:3, explain:"The maple leaf appears on the flag, coins, and the coat of arms.", chapter:"Canadian Symbols" },

  // ---------- Canada's Economy ----------
  { q:"What is the GST?", options:["A tax paid only by businesses","A tax on gasoline only","A provincial income tax","A federal tax on most goods and services"], answer:3, explain:"The Goods and Services Tax is added at the till on most purchases. Some provinces combine it with their own sales tax into a single harmonized tax.", chapter:"Canada's Economy" },
  { q:"What is Canada known for producing and exporting?", options:["Nothing at all","Oil, gas, grain, lumber, and minerals","Only bananas","Only cars"],answer:1, explain:"Canada exports natural resources like oil, gas, grain, lumber, and minerals.", chapter:"Canada's Economy" },
  { q:"Canada's economy is often described as based on which three types of industries?", options:["Banking only","Tourism only","Service, manufacturing, and natural resources","Farming, mining, and fishing only"],answer:2, explain:"Canada has service, manufacturing, and natural-resource industries.", chapter:"Canada's Economy" },

  // ---------- Canada's Regions ----------
  { q:"What is the capital city of Canada?", options:["Montreal","Toronto","Vancouver","Ottawa"],answer:3, explain:"Ottawa, in Ontario, is the capital of Canada.", chapter:"Canada's Regions" },
  { q:"How many provinces and territories does Canada have?", options:["10 provinces and 3 territories","12 provinces and 2 territories","8 provinces and 3 territories","10 provinces and 5 territories"], answer:0, explain:"Canada has 10 provinces and 3 territories.", chapter:"Canada's Regions" },
  { q:"Canada is the ____ largest country in the world by total area.", options:["First","Second","Fifth","Tenth"], answer:1, explain:"Canada is the second largest country in the world, after Russia.", chapter:"Canada's Regions" },
  { q:"Which three oceans border Canada?", options:["Pacific, Arctic, and Southern","Atlantic, Indian, and Arctic","Atlantic, Pacific, and Arctic","Atlantic, Pacific, and Indian"],answer:2, explain:"Canada is bordered by the Atlantic, Pacific, and Arctic Oceans.", chapter:"Canada's Regions" },
  { q:"Which three provinces are the Prairie provinces?", options:["Ontario, Quebec, and Nova Scotia","B.C., Yukon, and Alberta","New Brunswick, P.E.I., and Nova Scotia","Manitoba, Saskatchewan, and Alberta"],answer:3, explain:"The Prairie provinces are Manitoba, Saskatchewan, and Alberta.", chapter:"Canada's Regions" },
  { q:"What are the four Atlantic provinces?", options:["Nova Scotia, New Brunswick, P.E.I., Newfoundland and Labrador","Ontario, Quebec, Manitoba, Alberta","B.C., Alberta, Saskatchewan, Manitoba","Yukon, Nunavut, N.W.T., B.C."], answer:0, explain:"The Atlantic provinces are Nova Scotia, New Brunswick, Prince Edward Island, and Newfoundland and Labrador.", chapter:"Canada's Regions" },
  { q:"What are Canada's three territories?", options:["Nunavut, Labrador, and Yukon","Yukon, Northwest Territories, and Nunavut","Ontario, Quebec, and Alberta","Yukon, Alberta, and Manitoba"],answer:1, explain:"The three territories are Yukon, the Northwest Territories, and Nunavut.", chapter:"Canada's Regions" },
  { q:"Which province is mostly French-speaking?", options:["Manitoba","Ontario","Quebec","Alberta"],answer:2, explain:"Quebec is the only province where most people speak French as their first language.", chapter:"Canada's Regions" },
  { q:"What is the capital of Ontario?", options:["Hamilton","London","Ottawa","Toronto"],answer:3, explain:"Toronto is the capital of Ontario (Ottawa is the national capital).", chapter:"Canada's Regions" },
  { q:"What is the capital of Quebec?", options:["Quebec City","Laval","Gatineau","Montreal"],answer:0, explain:"Quebec City is the capital of the province of Quebec.", chapter:"Canada's Regions" },
  { q:"What is the capital of British Columbia?", options:["Vancouver","Victoria","Kelowna","Surrey"], answer:1, explain:"Victoria is the capital of British Columbia.", chapter:"Canada's Regions" },
  { q:"What is the capital of Alberta?", options:["Banff","Calgary","Edmonton","Red Deer"],answer:2, explain:"Edmonton is the capital of Alberta.", chapter:"Canada's Regions" },
  { q:"What is the capital of Manitoba?", options:["Brandon","Regina","Thunder Bay","Winnipeg"],answer:3, explain:"Winnipeg is the capital of Manitoba.", chapter:"Canada's Regions" },
  { q:"What is the capital of Saskatchewan?", options:["Regina","Moose Jaw","Prince Albert","Saskatoon"],answer:0, explain:"Regina is the capital of Saskatchewan.", chapter:"Canada's Regions" },
  { q:"What is the capital of Nova Scotia?", options:["Truro","Halifax","Sydney","Dartmouth"],answer:1, explain:"Halifax is the capital of Nova Scotia.", chapter:"Canada's Regions" },
  { q:"What is the capital of New Brunswick?", options:["Moncton","Saint John","Fredericton","Bathurst"], answer:2, explain:"Fredericton is the capital of New Brunswick.", chapter:"Canada's Regions" },
  { q:"What is the capital of Prince Edward Island?", options:["Summerside","Cornwall","Montague","Charlottetown"],answer:3, explain:"Charlottetown is the capital of Prince Edward Island.", chapter:"Canada's Regions" },
  { q:"What is the capital of Newfoundland and Labrador?", options:["St. John's","Gander","Mount Pearl","Corner Brook"],answer:0, explain:"St. John's is the capital of Newfoundland and Labrador.", chapter:"Canada's Regions" },
  { q:"What is the capital of Yukon?", options:["Iqaluit","Whitehorse","Dawson City","Yellowknife"],answer:1, explain:"Whitehorse is the capital of Yukon.", chapter:"Canada's Regions" },
  { q:"What is the capital of the Northwest Territories?", options:["Inuvik","Whitehorse","Yellowknife","Iqaluit"],answer:2, explain:"Yellowknife is the capital of the Northwest Territories.", chapter:"Canada's Regions" },
  { q:"What is the capital of Nunavut?", options:["Yellowknife","Whitehorse","Rankin Inlet","Iqaluit"],answer:3, explain:"Iqaluit is the capital of Nunavut.", chapter:"Canada's Regions" },
  { q:"Which ocean is on the WEST coast of Canada?", options:["The Pacific Ocean","The Arctic Ocean","The Indian Ocean","The Atlantic Ocean"],answer:0, explain:"The Pacific Ocean is on Canada's west coast (British Columbia).", chapter:"Canada's Regions" },
  { q:"Which country shares the longest border with Canada?", options:["Russia","The United States","Mexico","Greenland"], answer:1, explain:"Canada shares the world's longest border with the United States.", chapter:"Canada's Regions" },
  { q:"The Rocky Mountains run through Alberta and which other province?", options:["Ontario","Quebec","British Columbia","Nova Scotia"], answer:2, explain:"The Rocky Mountains run through Alberta and British Columbia.", chapter:"Canada's Regions" },
  { q:"The famous Niagara Falls are located in which province?", options:["Alberta","Manitoba","Quebec","Ontario"],answer:3, explain:"Niagara Falls is in Ontario, on the border with the United States.", chapter:"Canada's Regions" },
  { q:"Which is Canada's largest city by population?", options:["Toronto","Ottawa","Vancouver","Calgary"], answer:0, explain:"Toronto is Canada's largest city.", chapter:"Canada's Regions" },
  { q:"Canada's population is approximately…", options:["About 3 million","About 40 million","About 100 million","About 300 million"], answer:1, explain:"Canada's population is roughly 40 million people.", chapter:"Modern Canada" },
  { q:"What are the two official languages of Canada?", options:["English and Spanish","English and French","French and German","English and Italian"], answer:1, explain:"Canada's two official languages are English and French.", chapter:"Modern Canada" }
,
   /* +50 CITIZENSHIP_QUESTIONS */
   {q:"The Charter says you can deal with the federal government in which languages?",options:["French only, outside of Quebec","The language of your home province","English or French, your choice","English only, in every province"],answer:2,explain:"English and French are Canada's two official languages, so you may ask for federal services in either one.",chapter:"Rights and Responsibilities"},
   {q:"What do new Canadians promise at a citizenship ceremony?",options:["They pay a yearly citizenship fee","They promise to live in one province","They sign a rental agreement for a home","They take the Oath of Citizenship"],answer:3,explain:"At the ceremony new citizens take the Oath of Citizenship and receive their citizenship certificate. 🍁",chapter:"Rights and Responsibilities"},
   {q:"Freedom of peaceful assembly means people in Canada may...",options:["meet together in peaceful groups","ignore a law they do not like","enter any private building they wish","travel abroad without a passport"],answer:0,explain:"Peaceful assembly lets people meet, hold events and take part in peaceful gatherings together.",chapter:"Rights and Responsibilities"},
   {q:"How often must Parliament and each provincial legislature meet, at a minimum?",options:["At least once every ten years","At least once every 12 months","Only when a new law is needed","At least once every five years"],answer:1,explain:"The Charter requires elected assemblies to sit at least once a year so they can be held to account.",chapter:"Rights and Responsibilities"},
   {q:"In a province where your official language is the minority, the Charter gives parents the right to...",options:["choose any teacher they like","keep children home from school","have their children taught in that language","pay lower taxes for schools"],answer:2,explain:"Minority language education rights help English and French communities keep their language alive across Canada.",chapter:"Rights and Responsibilities"},
   {q:"Which word is used today instead of the older word 'Indian' for many Indigenous peoples?",options:["Newcomers","Settlers","Voyageurs","First Nations"],answer:3,explain:"The name 'First Nations' came into common use in the 1970s and is now the usual term for these communities.",chapter:"Who We Are"},
   {q:"What does the word 'Francophone' mean?",options:["Someone whose first language is French","Someone who works for the government","Someone born outside Canada","Someone who lives in Quebec"],answer:0,explain:"A Francophone speaks French as a first language, and an Anglophone speaks English as a first language.",chapter:"Who We Are"},
   {q:"The Acadians are descendants of French settlers who first made their homes in which part of Canada?",options:["The far North","The Atlantic region","The West Coast","The Prairie provinces"],answer:1,explain:"Acadian families settled around the Bay of Fundy in what are now the Maritime provinces.",chapter:"Who We Are"},
   {q:"Which language did the Métis develop?",options:["Gaelic","Icelandic","Michif","Inuktitut"],answer:2,explain:"Michif mixes French and Cree words and is still spoken by some Métis families today.",chapter:"Who We Are"},
   {q:"Along with the Aboriginal peoples, which two groups are called the founding peoples of Canada?",options:["The Germans and the Swedish","The Spanish and the Dutch","The Norse and the Irish","The French and the British"],answer:3,explain:"Canada's early history was shaped by Aboriginal peoples together with French and British settlers.",chapter:"Who We Are"},
   {q:"In the 1800s, the 'Underground Railroad' helped people escape slavery by leading them to...",options:["Canada","Iceland","Cuba","Mexico"],answer:0,explain:"Thousands of people followed this secret network of helpers north to freedom in Canada.",chapter:"Canada's History"},
   {q:"Canada's national police force began in 1873 under which name?",options:["The Canadian Rangers","The North-West Mounted Police","The Dominion Guard","The Queen's Rangers"],answer:1,explain:"The North-West Mounted Police kept order in the west and became the RCMP in 1920.",chapter:"Canada's History"},
   {q:"The Klondike Gold Rush of the 1890s brought thousands of people to which part of Canada?",options:["Vancouver Island","Northern Ontario","Yukon","Labrador"],answer:2,explain:"Gold seekers rushed to the Klondike River area, and the town of Dawson City grew almost overnight.",chapter:"Canada's History"},
   {q:"Who was the first woman elected to Canada's House of Commons?",options:["Nellie McClung","Emily Murphy","Thérèse Casgrain","Agnes Macphail"],answer:3,explain:"Agnes Macphail won her seat in 1921, the first federal election in which most women could vote.",chapter:"Canada's History"},
   {q:"Who was the first French-Canadian Prime Minister of Canada?",options:["Sir Wilfrid Laurier","Sir John A. Macdonald","Sir Charles Tupper","Sir Robert Borden"],answer:0,explain:"Sir Wilfrid Laurier became Prime Minister in 1896 and led the country for 15 years.",chapter:"Canada's History"},
   {q:"Canada was one of the countries that helped create which world organization in 1945?",options:["The Commonwealth Games","The United Nations","The Red Cross","The Olympic Games"],answer:1,explain:"Canada has been a member of the United Nations since it began, and has often joined peacekeeping missions.",chapter:"Modern Canada"},
   {q:"What did the Official Languages Act of 1969 do?",options:["Ended the teaching of English in the west","Created a new national anthem for Canada","Made English and French equal in the federal government","Made French the only language of Quebec schools"],answer:2,explain:"Since 1969, federal offices across the country must be able to serve people in English and in French.",chapter:"Modern Canada"},
   {q:"La Francophonie is an international group of countries that share...",options:["the same money","a border with Canada","the same head of state","the French language"],answer:3,explain:"Canada takes part in La Francophonie because French is one of its two official languages. 🇨🇦",chapter:"Modern Canada"},
   {q:"The Canadarm, built in Canada, was a robotic arm used for what?",options:["Working in space on spacecraft","Building cars in a factory","Lifting boats in a canal","Digging mines deep underground"],answer:0,explain:"Canadian engineers built this robotic arm to move equipment in space, and it made Canada famous in space science. 🚀",chapter:"Modern Canada"},
   {q:"In 1960, which group gained the right to vote in federal elections?",options:["New immigrants","First Nations people","Women over 21","People who did not own land"],answer:1,explain:"First Nations people could finally vote in federal elections in 1960 without giving up their status.",chapter:"Modern Canada"},
   {q:"What is the name of the Governor General's official home in Ottawa?",options:["Dominion House","Laurier Manor","Rideau Hall","Maple House"],answer:2,explain:"Rideau Hall is where the Governor General lives, works and welcomes visitors from other countries.",chapter:"How Canadians Govern Themselves"},
   {q:"The party with the second-largest number of seats in the House of Commons is called the...",options:["Cabinet council","Second chamber","Senate caucus","Official Opposition"],answer:3,explain:"The job of the Official Opposition is to question the government and suggest better ideas.",chapter:"How Canadians Govern Themselves"},
   {q:"What is a 'majority government'?",options:["A government with more than half the seats","A government chosen by the Senate","A government that lasts more than five years","A government led by two parties together"],answer:0,explain:"With more than half the seats, the governing party can usually pass its bills in the House of Commons.",chapter:"How Canadians Govern Themselves"},
   {q:"What is the main job of the Speaker of the House of Commons?",options:["To choose the Cabinet ministers","To keep order during debates","To sign bills into law","To write all new laws"],answer:1,explain:"The Speaker is chosen by the members and makes sure debates follow the rules and stay fair.",chapter:"How Canadians Govern Themselves"},
   {q:"Where do Canada's three territories get their powers from?",options:["The city councils","The Supreme Court","The Parliament of Canada","The nearest province"],answer:2,explain:"Provinces get their powers from the Constitution, while territories receive theirs from the federal Parliament.",chapter:"How Canadians Govern Themselves"},
   {q:"What is the National Register of Electors?",options:["A list of everyone who pays taxes","A book of election results","A list of members of Parliament","A list of people who may vote"],answer:3,explain:"Elections Canada keeps this permanent list so that voters can be sent information before each election.",chapter:"Federal Elections"},
   {q:"What arrives in the mail to tell a registered voter where and when to vote?",options:["A voter information card","A passport application","A tax receipt","A ballot paper"],answer:0,explain:"The card gives the address of your polling station and the day and hours it is open.",chapter:"Federal Elections"},
   {q:"What can you do if you cannot vote on election day?",options:["Send your choice by text message","Vote at an advance poll","Vote twice at the next election","Ask a neighbour to vote for you"],answer:1,explain:"Advance polls open days before the election, and you may also vote by mail or at an Elections Canada office.",chapter:"Federal Elections"},
   {q:"How is the winner chosen in each riding in a federal election?",options:["The Senate picks from the top two","The candidate must win half of all votes","The candidate with the most votes wins","A second vote is held one month later"],answer:2,explain:"This system is called first-past-the-post: the leading candidate wins the seat, even without half the votes.",chapter:"Federal Elections"},
   {q:"Who may run as a candidate in a federal election?",options:["Anyone living in Canada for one year","Only people born in Canada","Only people who own a home","Any Canadian citizen aged 18 or over"],answer:3,explain:"Candidates must be Canadian citizens at least 18 years old on election day.",chapter:"Federal Elections"},
   {q:"What is the main job of a judge in a Canadian court?",options:["To apply the law and keep the trial fair","To choose the police officers","To arrest people who break the law","To write the country's laws"],answer:0,explain:"Judges are independent, which means no one can tell them how to decide a case.",chapter:"The Justice System"},
   {q:"How many judges sit on the Supreme Court of Canada?",options:["Five","Nine","Twelve","Fifteen"],answer:1,explain:"Nine judges hear the country's most important cases, and three of them must come from Quebec.",chapter:"The Justice System"},
   {q:"Most provinces use common law, but Quebec uses a different system called the...",options:["Royal Code","Common Charter","Civil Code","Charter Code"],answer:2,explain:"Quebec's Civil Code comes from French legal tradition and covers matters like contracts and property.",chapter:"The Justice System"},
   {q:"Which court would you use for a small money disagreement, such as unpaid work?",options:["A provincial legislature","The Supreme Court of Canada","A federal appeal court","Small claims court"],answer:3,explain:"Small claims courts are simple and low-cost, and people often go without a lawyer.",chapter:"The Justice System"},
   {q:"What can a person do if they need a lawyer but cannot pay for one?",options:["Apply for legal aid","Ask the judge to be their lawyer","Ask the police for legal advice","Wait until the case is closed"],answer:0,explain:"Legal aid offices help people with low incomes get legal advice and a lawyer. ⚖️",chapter:"The Justice System"},
   {q:"The Canadian flag is often known by which nickname?",options:["The Red Ensign","The Maple Leaf","The Northern Star","The Beaver Banner"],answer:1,explain:"People call the flag the Maple Leaf because of the single red leaf in its centre.",chapter:"Canadian Symbols"},
   {q:"What is the Order of Canada?",options:["A rule book for Parliament","A yearly parade in Ottawa","One of Canada's highest honours","A list of national holidays"],answer:2,explain:"It honours people who have made a real difference to their community or country over a lifetime.",chapter:"Canadian Symbols"},
   {q:"Which popular sport was invented by a Canadian?",options:["Tennis","Golf","Cricket","Basketball"],answer:3,explain:"James Naismith, born in Ontario, invented basketball in 1891 while teaching young people. 🏀",chapter:"Canadian Symbols"},
   {q:"Which tree is the national tree of Canada?",options:["The maple","The pine","The birch","The spruce"],answer:0,explain:"The maple became Canada's official tree in 1996, and its leaf has been a symbol for much longer.",chapter:"Canadian Symbols"},
   {q:"In which year was the song 'O Canada' first performed?",options:["1880","1920","1945","1967"],answer:0,explain:"The song was first sung in Quebec City in 1880 and became the official national anthem 100 years later.",chapter:"Canadian Symbols"},
   {q:"What is the name of Canada's currency?",options:["The Canadian pound","The Canadian dollar","The Canadian franc","The Canadian crown"],answer:1,explain:"Canadians pay in dollars and cents, and the coins carry symbols such as the loon and the beaver.",chapter:"Canada's Economy"},
   {q:"Most people in Canada work in which kind of industry?",options:["Fishing industries","Mining industries","Service industries","Farming industries"],answer:2,explain:"About three out of four working Canadians have service jobs, such as teaching, health care, sales or transport.",chapter:"Canada's Economy"},
   {q:"Which province is best known for producing oil and natural gas?",options:["Prince Edward Island","Nova Scotia","Manitoba","Alberta"],answer:3,explain:"The oil and gas fields of Alberta, including the oil sands, are a major part of Canada's economy.",chapter:"Canada's Economy"},
   {q:"Fishing has been a leading industry for centuries in which region of Canada?",options:["Atlantic Canada","Central Ontario","The Yukon interior","The Prairies"],answer:0,explain:"The rich waters off the East Coast drew fishing boats to Newfoundland and the Maritimes long ago. 🐟",chapter:"Canada's Economy"},
   {q:"Which province is the centre of Canada's car-making industry?",options:["British Columbia","Ontario","Saskatchewan","New Brunswick"],answer:1,explain:"Southern Ontario has many factories that build vehicles and parts for sale in Canada and abroad.",chapter:"Canada's Economy"},
   {q:"Which two provinces make up the area called Central Canada?",options:["Alberta and Saskatchewan","Manitoba and Ontario","Ontario and Quebec","Quebec and New Brunswick"],answer:2,explain:"Ontario and Quebec together are home to more than half of all Canadians.",chapter:"Canada's Regions"},
   {q:"Which is the largest province in Canada by land area?",options:["Ontario","British Columbia","Alberta","Quebec"],answer:3,explain:"Quebec is bigger than any other province, though the territory of Nunavut covers even more land.",chapter:"Canada's Regions"},
   {q:"What is the longest river in Canada?",options:["The Mackenzie River","The Saint John River","The Fraser River","The Ottawa River"],answer:0,explain:"The Mackenzie flows north through the Northwest Territories to the Arctic Ocean.",chapter:"Canada's Regions"},
   {q:"What is the highest mountain in Canada?",options:["Mount Royal","Mount Logan","Mount Robson","Mount Tremblant"],answer:1,explain:"Mount Logan stands in the southwest corner of Yukon and is the second highest peak in North America.",chapter:"Canada's Regions"},
   {q:"Which is the smallest province in Canada?",options:["New Brunswick","Newfoundland and Labrador","Prince Edward Island","Nova Scotia"],answer:2,explain:"Prince Edward Island is small enough to drive across in a few hours, and a long bridge links it to the mainland.",chapter:"Canada's Regions"},

  /* ---------- Added 7 August 2026 — 52 more practice questions ----------
     Same sources and style as the sets above. Reviewed for accuracy. */
  { q:"Which document from 1215 is one of the foundations of Canadian law and freedoms?", options:["Magna Carta", "The Treaty of Paris", "The Quebec Act", "The Statute of Westminster"], answer:0, explain:"Magna Carta, signed in England in 1215, is often called the Great Charter of Freedoms. It gave us ideas such as freedom under law and trial by jury.", chapter:"Rights and Responsibilities" },
  { q:"The Charter lists four fundamental freedoms. Which one protects your right to join a union, a club or a political party?", options:["Minority language education rights","Freedom of association","Mobility rights","Equality rights"], answer:1, explain:"Freedom of association lets people join together in groups of their own choosing. The other fundamental freedoms are conscience and religion, thought and expression, and peaceful assembly.", chapter:"Rights and Responsibilities" },
  { q:"Which of these is a responsibility of Canadian citizenship rather than a right?", options:["Speaking English or French", "Applying for a passport", "Serving on a jury when called", "Voting in elections"], answer:2, explain:"Serving on a jury is a duty. So is obeying the law, taking responsibility for yourself and your family, and helping others in the community.", chapter:"Rights and Responsibilities" },
  { q:"If the police arrest you in Canada, what does the Charter guarantee?", options:["That you will be released within one hour","That your family will be told before you are","A free lawyer for every case","To be told why and to speak to a lawyer without delay"], answer:3, explain:"You must be told promptly why you are being held, and you may contact a lawyer right away. Legal aid can pay for that lawyer if you cannot afford one.", chapter:"Rights and Responsibilities" },
  { q:"What does mobility rights mean for a Canadian citizen?", options:["The right to live and work anywhere in Canada, and to enter and leave the country", "The right to free public transit", "The right to change your name", "The right to a driver's licence"], answer:0, explain:"Mobility rights let you live and seek work in any province or territory, and enter, stay in or leave Canada freely.", chapter:"Rights and Responsibilities" },
  { q:"Caring for Canada's parks, rivers and historic places is described in the citizenship guide as...", options:["something optional for newcomers","the duty of city councils only","a responsibility of citizenship","a task for the federal government alone"], answer:2, explain:"Protecting and enjoying Canada's heritage and environment is one of the responsibilities the guide sets out, alongside obeying the law and helping others in the community.", chapter:"Rights and Responsibilities" },
  { q:"Which day each June honours the First Nations, Inuit and Metis?", options:["National Indigenous Peoples Day","Canada Day","Labour Day","Victoria Day"], answer:0, explain:"National Indigenous Peoples Day falls on June 21, the summer solstice, a date many Indigenous communities have long marked with celebrations.", chapter:"Who We Are" },
  { q:"What does the word 'Anglophone' mean?", options:["Someone who speaks both official languages","Someone who works in radio or television","Someone born in England","Someone whose first language is English"], answer:3, explain:"Anglophones are English-speaking Canadians and francophones are French-speaking Canadians. Many Canadians speak both, and millions speak a third language at home.", chapter:"Who We Are" },
  { q:"What is the deportation of the Acadians, which began in 1755, known as?", options:["The Great Coalition","The Great Upheaval","The Great Migration","The Quiet Revolution"], answer:1, explain:"British colonial officials deported most of the Acadian population between 1755 and 1763. Many families later returned, and Acadian communities are strong in the Maritimes today.", chapter:"Who We Are" },
  { q:"Roughly what share of Canadians report French as their first language?", options:["About three quarters", "About one quarter", "About one half", "About one tenth"], answer:1, explain:"Around a quarter of Canadians speak French as a first language, most of them in Quebec, with about a million francophones living in other provinces.", chapter:"Who We Are" },
  { q:"The Constitutional Act of 1791 divided the old province of Quebec into which two colonies?", options:["New France and Acadia","Canada East and Rupert's Land","Ontario and Quebec","Upper Canada and Lower Canada"], answer:3, explain:"Upper Canada, later Ontario, was mainly English-speaking, while Lower Canada, later Quebec, was mainly French-speaking. Each was given an elected assembly for the first time.", chapter:"Canada's History" },
  { q:"In 1793 which colony passed one of the first laws in the British Empire to limit slavery?", options:["Newfoundland","Lower Canada","Upper Canada","Nova Scotia"], answer:2, explain:"Lieutenant Governor John Graves Simcoe pushed the law through the assembly of Upper Canada, today's Ontario. Slavery was abolished throughout the British Empire in 1833.", chapter:"Canada's History" },
  { q:"What happened in Halifax harbour in December 1917?", options:["The first Canadian submarine was launched","A fire closed the shipyards for a year","A hurricane sank the fishing fleet","Two ships collided and a huge explosion destroyed part of the city"], answer:3, explain:"A ship loaded with munitions caught fire after a collision and blew up, killing about 2,000 people. Boston sent help so quickly that Nova Scotia still sends that city a Christmas tree every year.", chapter:"Canada's History" },
  { q:"Canadian troops led the liberation of which country in 1944 and 1945?", options:["The Netherlands","Norway","Greece","Denmark"], answer:0, explain:"The Dutch royal family had taken refuge in Ottawa during the war. The Netherlands still sends tulips to Ottawa every year in thanks.", chapter:"Canada's History" },
  { q:"Which invention did Alexander Graham Bell work out at his family home in Brantford, Ontario?", options:["The electric light bulb","The radio","The steam engine","The telephone"], answer:3, explain:"Bell worked out the idea for the telephone at Brantford in 1874 and later made the first long-distance call from there. He spent his later years in Nova Scotia.", chapter:"Canada's History" },
  { q:"Thousands of Chinese workers helped build the railway through the mountains. What did Canada then charge Chinese immigrants, starting in 1885?", options:["A deposit for citizenship","A head tax","A land fee","A tax on railway tickets"], answer:1, explain:"The head tax applied only to Chinese immigrants and rose until 1923, when almost all Chinese immigration was barred. Parliament apologized in 2006 and offered payments to those affected.", chapter:"Canada's History" },
  { q:"Which two provinces were created in 1905?", options:["Nova Scotia and New Brunswick","Manitoba and British Columbia","Alberta and Saskatchewan","Ontario and Quebec"], answer:2, explain:"Both were carved out of the North-West Territories as settlers arrived to farm the prairie. Manitoba had already joined Confederation in 1870.", chapter:"Canada's History" },
  { q:"What was the residential school system?", options:["Schools built along the railway", "Government-funded schools that separated Indigenous children from their families and cultures", "The first Canadian universities", "Boarding schools for immigrant children"], answer:1, explain:"About 150,000 Indigenous children attended. In 2008 the Government of Canada formally apologized, and the Truth and Reconciliation Commission documented the harm.", chapter:"Canada's History" },
  { q:"What are the three branches of government in Canada?", options:["House, Senate and Monarch", "Police, courts and prisons", "Executive, legislative and judicial", "Federal, provincial and municipal"], answer:2, explain:"The executive carries out the laws, the legislative branch makes them, and the judicial branch interprets them and settles disputes.", chapter:"How Canadians Govern Themselves" },
  { q:"Until what age may a senator normally serve?", options:["65","70","75","There is no age limit"], answer:2, explain:"Senators must retire at 75. The Senate studies bills carefully and is sometimes called the chamber of sober second thought.", chapter:"How Canadians Govern Themselves" },
  { q:"On a First Nations reserve, who is normally elected by the community to govern it?", options:["A mayor and city council","A chief and band council","A Lieutenant Governor","A provincial minister"], answer:1, explain:"Members elect a chief and councillors who look after local matters such as housing, schools and roads. Many First Nations are also negotiating wider self-government agreements.", chapter:"How Canadians Govern Themselves" },
  { q:"What are the elected members of most provincial legislatures called?", options:["Senators","City councillors","Members of Parliament","Members of the Legislative Assembly"], answer:3, explain:"Most provinces elect MLAs. Ontario calls them MPPs, and Quebec calls them MNAs, members of the National Assembly.", chapter:"How Canadians Govern Themselves" },
  { q:"What is a bill called once it has passed both houses and received Royal Assent?", options:["A regulation", "A petition", "An Act, which becomes law", "A motion"], answer:2, explain:"A bill must pass the House of Commons and the Senate, then receive Royal Assent from the Governor General, before it becomes an Act of Parliament.", chapter:"How Canadians Govern Themselves" },
  { q:"What is the role of the Opposition in Parliament?", options:["To write the budget", "To appoint judges", "To command the armed forces", "To question the government and hold it accountable"], answer:3, explain:"The party with the second most seats becomes the Official Opposition, sometimes called Her or His Majesty's Loyal Opposition. Its job is to challenge government decisions.", chapter:"How Canadians Govern Themselves" },
  { q:"How are the ballots counted once the polls close in a federal election?", options:["By computers in Ottawa","By the local police","By hand, in front of witnesses","By the Prime Minister's office"], answer:2, explain:"Election officers count the paper ballots at each polling station, and representatives of the candidates may watch. Results are usually known the same evening.", chapter:"Federal Elections" },
  { q:"How can a voter who will be away from home on election day and during the advance polls still vote?", options:["By telephone","By special ballot, usually by mail","By asking a neighbour to vote for them","They cannot vote at all"], answer:1, explain:"Elections Canada offers a special ballot to voters who are travelling, living abroad or in hospital. You have to apply for it before the deadline.", chapter:"Federal Elections" },
  { q:"Besides federal elections, in which other elections do Canadians vote?", options:["Municipal elections only","Elections for Supreme Court judges","Elections for senators","Provincial or territorial and municipal elections"], answer:3, explain:"Each of the three levels of government is chosen by voters, although the dates and rules for each election are set separately.", chapter:"Federal Elections" },
  { q:"What normally happens when no party wins a majority of seats in the House of Commons?", options:["A new election is held immediately", "The Senate chooses the government", "The Governor General governs alone", "A minority government is formed and needs support from other parties"], answer:3, explain:"The party with the most seats usually forms a minority government. It must win the support of members from other parties to pass legislation.", chapter:"Federal Elections" },
  { q:"What is a political party's platform?", options:["The set of promises and plans it offers voters","The list of its members","The building where it meets","The stage used at its rallies"], answer:0, explain:"Parties publish a platform during a campaign so that voters can compare what each one would do in government.", chapter:"Federal Elections" },
  { q:"Who brings a criminal charge to court on behalf of the public in Canada?", options:["The judge","A Member of Parliament","The victim's family","A Crown prosecutor"], answer:3, explain:"Police lay the charge and a Crown prosecutor presents the case in court. The accused has the right to defend themselves and to be represented by a lawyer.", chapter:"The Justice System" },
  { q:"What is the difference between criminal law and civil law in Canada?", options:["Civil law applies only to companies","There is no real difference","Criminal law covers offences against society, while civil law settles disputes between people","Criminal law applies only to citizens"], answer:2, explain:"In a criminal case the Crown prosecutes on behalf of everyone. In a civil case one person or business sues another, often over money, property or a contract.", chapter:"The Justice System" },
  { q:"What does it mean to say that judges in Canada are independent?", options:["They decide cases free from political interference","They may write new laws","They are elected by voters","They work only part of the year"], answer:0, explain:"Judges are appointed rather than elected, and they cannot be removed because a government dislikes a decision. That independence is part of the rule of law.", chapter:"The Justice System" },
  { q:"What is the purpose of the court system in Canada?", options:["To settle disputes and make sure the law is applied fairly to everyone", "To write new laws", "To collect taxes", "To elect the government"], answer:0, explain:"Courts resolve disputes and apply the law. A key idea is the rule of law: no person or government is above the law.", chapter:"The Justice System" },
  { q:"Which flag did Canada commonly fly before the maple leaf flag?", options:["A green flag with a beaver","A white flag with a single star","The flag of New France","The Canadian Red Ensign"], answer:3, explain:"The Red Ensign carried the Union Jack in the corner and Canada's shield on a red field. Parliament chose the maple leaf design after a long debate in 1964.", chapter:"Canadian Symbols" },
  { q:"Which bird appears on the Canadian one-dollar coin?", options:["The grey jay","The snowy owl","The common loon","The Canada goose"], answer:2, explain:"The loon gives the coin its nickname, the loonie. The two-dollar coin that came later is known as the toonie.", chapter:"Canadian Symbols" },
  { q:"Which trophy, donated by a Governor General, goes to the champions of professional hockey?", options:["The Stanley Cup","The Vanier Cup","The Memorial Cup","The Grey Cup"], answer:0, explain:"Lord Stanley donated the cup in 1892 for the best hockey team in Canada. The Grey Cup, donated by another Governor General, goes to the football champions.", chapter:"Canadian Symbols" },
  { q:"Which holiday in late May honours the Sovereign?", options:["Thanksgiving","Boxing Day","Labour Day","Victoria Day"], answer:3, explain:"Victoria Day falls on the Monday before May 25. It marks Queen Victoria's birthday and is also the Sovereign's official birthday in Canada.", chapter:"Canadian Symbols" },
  { q:"What is Canada's highest award for military valour?", options:["The Victoria Cross","The Star of Courage","The Meritorious Service Medal","The Polar Medal"], answer:0, explain:"The Victoria Cross recognizes the most conspicuous bravery in the face of the enemy. Fewer than one hundred Canadians have ever received it.", chapter:"Canadian Symbols" },
  { q:"What is the name of Canada's system of publicly funded health care?", options:["The National Health Service", "Blue Cross", "Medicare", "Social Security"], answer:2, explain:"Medicare is paid for by taxes and administered by the provinces and territories, so basic medical services are available to everyone.", chapter:"Modern Canada" },
  { q:"What does multiculturalism mean in Canada?", options:["Everyone must adopt one culture", "Only two cultures are recognized", "Immigration is limited by culture", "People may keep their cultural heritage while sharing Canadian values and laws"], answer:3, explain:"Canada was the first country in the world to adopt multiculturalism as an official policy, in 1971.", chapter:"Modern Canada" },
  { q:"In which war of 1950 to 1953 did more than 25,000 Canadians serve with a United Nations force?", options:["The Boer War","The Korean War","The First World War","The Gulf War"], answer:1, explain:"Canada sent soldiers, ships and aircraft to Korea, and 516 Canadians died there. Monuments in Ottawa and in Korea honour them.", chapter:"Modern Canada" },
  { q:"During the Second World War thousands of Japanese Canadians were moved away from the West Coast and their property was sold. What did the Government of Canada do in 1988?", options:["Apologized and offered compensation","Returned the fishing boats only","Renamed the camps","Said nothing about it"], answer:0, explain:"The 1988 agreement included a formal apology in Parliament and payments to those who had been interned. Their full citizenship rights had been restored after the war.", chapter:"Modern Canada" },
  { q:"Canada belongs to which group of leading industrial economies?", options:["The African Union","The G7","OPEC","The European Union"], answer:1, explain:"Canada has belonged to the group since 1976 and hosts its summit in turn with the other members. It also takes part in the wider G20.", chapter:"Canada's Economy" },
  { q:"Canada shares the longest undefended border in the world with which country, also its biggest trading partner?", options:["China", "The United Kingdom", "Mexico", "The United States"], answer:3, explain:"The United States is by far Canada's largest trading partner, and the two countries share the longest undefended border in the world.", chapter:"Canada's Economy" },
  { q:"What is a Social Insurance Number used for?", options:["Working in Canada and receiving government benefits", "Voting in elections", "Entering the country", "Registering a vehicle"], answer:0, explain:"You need a SIN to work and to receive benefits. Keep it private, because it can be used for identity theft.", chapter:"Canada's Economy" },
  { q:"Why do Canadians pay taxes?", options:["To buy Canadian products", "To fund roads, schools, health care and other public services", "To repay the Crown", "Only to fund the military"], answer:1, explain:"Taxes pay for roads, schools, hospitals, policing and social programs. Filing an income tax return each year is a responsibility of living in Canada.", chapter:"Canada's Economy" },
  { q:"Which region is known as the industrial and manufacturing heartland of Canada?", options:["The Atlantic provinces", "The North", "Central Canada, meaning Ontario and Quebec", "The Prairies"], answer:2, explain:"Ontario and Quebec together hold more than half the country's population and produce most of Canada's manufactured goods.", chapter:"Canada's Regions" },
  { q:"Which city is the largest in Quebec and the second largest in Canada?", options:["Quebec City","Montreal","Ottawa","Laval"], answer:1, explain:"Montreal grew up around the St. Lawrence River and is one of the largest French-speaking cities in the world.", chapter:"Canada's Regions" },
  { q:"What is the Canadian Shield?", options:["A large area of ancient rock covering much of the country, rich in minerals", "A mountain range in British Columbia", "A defence agreement with the United States", "The plains of southern Manitoba"], answer:0, explain:"The Shield covers much of northern and central Canada. Its thin soil limits farming, but it is one of the richest mineral regions on Earth.", chapter:"Canada's Regions" },
  { q:"Which is the only province where French is the sole official language?", options:["Manitoba", "Quebec", "New Brunswick", "Ontario"], answer:1, explain:"Quebec is the only province whose sole official language is French. New Brunswick is the only officially bilingual province.", chapter:"Canada's Regions" },
  { q:"What is the largest lake lying entirely inside Canada?", options:["Great Bear Lake","Lake Winnipeg","Lake Ontario","Lake Superior"], answer:0, explain:"Great Bear Lake lies in the Northwest Territories and touches the Arctic Circle. The Great Lakes are bigger, but Canada shares them with the United States.", chapter:"Canada's Regions" },
  { q:"Which is Canada's Pacific gateway and busiest west coast port city?", options:["Victoria", "Prince Rupert", "Kelowna", "Vancouver"], answer:3, explain:"Vancouver is Canada's main Pacific port and its gateway to trade with Asia. Victoria, on Vancouver Island, is the provincial capital.", chapter:"Canada's Regions" },

  /* ---------- Added 8 August 2026 — 31 more ----------
     Weighted to the chapters that were still thinnest. */
  { q:"Applicants aged 18 to 54 must prove they can do what in English or French?", options:["Speak and understand at a basic, everyday level","Write a university-level essay","Speak both languages fluently","Nothing — there is no language requirement"], answer:0, explain:"Adequate knowledge of one official language is part of the citizenship requirements. An officer can judge it from the way you speak during your interview, not only from a written test.", chapter:"About the Test" },
  { q:"In which languages is the citizenship test written?", options:["Any official language of your choice", "English or French", "English only", "French only"], answer:1, explain:"You may take it in either official language. The test checks your knowledge of Canada, and your language ability is assessed separately.", chapter:"About the Test" },
  { q:"What happens if you do not pass the citizenship test on your first try?", options:["You must wait five years", "You must leave Canada", "You are normally given another chance to take it again", "Your application is cancelled"], answer:2, explain:"Not passing the first time is not the end. Within your 30-day test period you get up to three chances to pass, and if all three go wrong you are invited to a hearing with a citizenship officer.", chapter:"About the Test" },
  { q:"Which age group is required to take the citizenship test?", options:["Everyone, at any age", "Only applicants under 18", "Only applicants over 55", "Applicants aged 18 to 54"], answer:3, explain:"The knowledge and language requirements apply to applicants between 18 and 54 at the time they apply.", chapter:"About the Test" },
  { q:"What did the House of Commons recognize in 2006 about the Quebecois?", options:["That French is Canada's only official language","That Quebec may write its own constitution","That they form a nation within a united Canada","That Quebec is a separate country"], answer:2, explain:"The motion recognized the Quebecois as a nation within a united Canada. It was a symbolic recognition and did not change Quebec's place in Confederation.", chapter:"Who We Are" },
  { q:"What does the word Inuit mean?", options:["The travellers", "The people", "The north", "The hunters"], answer:1, explain:"Inuit means the people in Inuktitut. Most Inuit live in the Arctic, across Nunavut, the Northwest Territories, northern Quebec and Labrador.", chapter:"Who We Are" },
  { q:"What is the main language of the Inuit called?", options:["Inuktitut","Cree","Innu","Michif"], answer:0, explain:"Inuktitut is spoken across the Arctic and is written both in syllabics and in the Roman alphabet. It is one of the official languages of Nunavut.", chapter:"Who We Are" },
  { q:"Outside Quebec, the largest French-speaking communities are found in which two provinces?", options:["Nova Scotia and Prince Edward Island","British Columbia and Manitoba","Alberta and Saskatchewan","Ontario and New Brunswick"], answer:3, explain:"Ontario has the most francophones by number and New Brunswick has the largest share of its population. French-speaking communities live in every province and territory.", chapter:"Who We Are" },
  { q:"Who appoints judges to the Supreme Court of Canada?", options:["The Governor General on the advice of the Prime Minister", "Voters in a national election", "The provinces together", "The Chief Justice alone"], answer:0, explain:"Judges are appointed, not elected. Once appointed they are independent of government, which is what makes the courts impartial.", chapter:"The Justice System" },
  { q:"Where are most criminal and civil cases in Canada heard first?", options:["In the Supreme Court of Canada","In provincial and territorial courts","In the Senate","In the Federal Court"], answer:1, explain:"Provincial and territorial courts handle the great majority of cases, from traffic matters to serious crimes. Only a small number of cases ever reach the Supreme Court.", chapter:"The Justice System" },
  { q:"What is a jury in a Canadian court?", options:["A team of lawyers", "A group of police officers", "A group of ordinary citizens who decide the facts of a case", "A panel of judges"], answer:2, explain:"Serving on a jury when called is one of the responsibilities of citizenship. Jurors decide what happened; the judge decides the law.", chapter:"The Justice System" },
  { q:"What kind of law does the federal government make?", options:["Traffic law in each province", "School rules", "Municipal by-laws", "Criminal law, which is the same across the whole country"], answer:3, explain:"Criminal law is federal, so it is identical in every province and territory. Provinces handle things like highway traffic acts.", chapter:"The Justice System" },
  { q:"What is the Canadian Charter of Rights and Freedoms part of?", options:["The Constitution of Canada", "An ordinary law that Parliament can repeal easily", "A United Nations treaty", "A provincial statute"], answer:0, explain:"Because the Charter is part of the Constitution, it is much harder to change than an ordinary law, and courts can strike down laws that conflict with it.", chapter:"Modern Canada" },
  { q:"What did Canada celebrate in 1967?", options:["The opening of the first railway","Its 50th birthday","Its 100th birthday","The end of the Second World War"], answer:2, explain:"The centennial year brought Expo 67 in Montreal, community projects in towns across the country and the creation of the Order of Canada.", chapter:"Modern Canada" },
  { q:"What is peacekeeping, which Canada is known for?", options:["Selling weapons abroad", "Closing the border in wartime", "Sending forces to help keep peace between opposing sides in a conflict", "Refusing to join any alliance"], answer:2, explain:"Canadians have served in peacekeeping missions around the world. Lester B. Pearson won the Nobel Peace Prize in 1957 for the idea.", chapter:"Modern Canada" },
  { q:"Which international organizations is Canada a member of?", options:["The United Nations only", "NATO only", "None of them", "The United Nations, NATO, the Commonwealth and la Francophonie"], answer:3, explain:"Canada belongs to all four. Membership in both the Commonwealth and la Francophonie reflects its British and French heritage.", chapter:"Modern Canada" },
  { q:"What does the Bank of Canada do?", options:["Sets the country's main interest rate and issues its banknotes", "Lends money to individuals", "Collects income tax", "Runs the stock exchange"], answer:0, explain:"It is the central bank. It sets monetary policy and prints the bills in your wallet, but it does not offer personal accounts.", chapter:"Canada's Economy" },
  { q:"What is the name of Canada's trade agreement with the United States and Mexico?", options:["The Commonwealth Accord", "CUSMA, also called USMCA", "NATO", "NAFTA, which it replaced"], answer:1, explain:"CUSMA replaced NAFTA. Trade with the United States dominates Canada's economy more than any other single relationship.", chapter:"Canada's Economy" },
  { q:"What does Employment Insurance provide?", options:["Money to buy a first home","Free health care","Temporary payments to people who lose their job","A pension for everyone at 60"], answer:2, explain:"Workers and employers pay into the plan, and it gives short-term income to people who lose work through no fault of their own. It also covers maternity and parental leave.", chapter:"Canada's Economy" },
  { q:"When must most Canadians file their income tax return each year?", options:["By 31 December", "By 1 July", "There is no deadline", "By 30 April"], answer:3, explain:"Filing a return is a responsibility of living in Canada. It is also how you receive benefits and credits you may be entitled to.", chapter:"Canada's Economy" },
  { q:"What is a by-election?", options:["A vote held in one riding between general elections","A second count of the ballots","An election for the Senate","A vote held inside a political party"], answer:0, explain:"When a seat becomes vacant between general elections, the voters of that riding alone choose a new Member of Parliament.", chapter:"Federal Elections" },
  { q:"Who becomes Prime Minister after a federal election?", options:["The leader of the Senate", "The leader of the party with the most seats in the House of Commons", "The candidate with the most personal votes", "The Governor General's choice from any party"], answer:1, explain:"You do not vote for the Prime Minister directly. You elect a Member of Parliament for your riding, and the party with the most seats normally forms government.", chapter:"Federal Elections" },
  { q:"What should you do if you are not on the voters list on election day?", options:["You must wait for the next election", "You must vote by mail only", "You can still register at the polling station with the right identification", "You cannot vote at all"], answer:2, explain:"You may register in person on election day. Bring identification showing your name and address.", chapter:"Federal Elections" },
  { q:"Who composed the music of 'O Canada'?", options:["Healey Willan","Calixa Lavallée","Glenn Gould","Oscar Peterson"], answer:1, explain:"Calixa Lavallée wrote the music in 1880 for a Saint-Jean-Baptiste Day celebration in Quebec City. The original French words were written by Adolphe-Basile Routhier.", chapter:"Canadian Symbols" },
  { q:"What is the royal anthem of Canada?", options:["God Save the King", "O Canada", "Rule Britannia", "The Maple Leaf Forever"], answer:0, explain:"God Save the King is the royal anthem, played in the presence of members of the Royal Family. O Canada is the national anthem.", chapter:"Canadian Symbols" },
  { q:"What do the two red bands on the Canadian flag represent?", options:["Summer and winter", "The Atlantic and Pacific oceans", "The two official languages", "The Crown and Parliament"], answer:1, explain:"Red and white are Canada's official colours, and the bands are often read as the two oceans on either side of the country.", chapter:"Canadian Symbols" },
  { q:"Who reached Canada's Atlantic coast in 1497 and claimed it for England?", options:["Étienne Brûlé","Henry Hudson","John Cabot","Martin Frobisher"], answer:2, explain:"John Cabot was an Italian navigator sailing for England. He drew the first map of Canada's east coast and reported waters full of cod.", chapter:"Canada's History" },
  { q:"Which Shawnee chief fought alongside British and Canadian forces in the War of 1812?", options:["Tecumseh","Pontiac","Big Bear","Poundmaker"], answer:0, explain:"Tecumseh led a confederacy of First Nations and worked closely with Major-General Isaac Brock. He was killed in battle in 1813 and is honoured as a defender of Canada.", chapter:"Canada's History" },
  { q:"Which province was the first to give women the right to vote, in 1916?", options:["Ontario","Manitoba","Nova Scotia","Alberta"], answer:1, explain:"Manitoba women won the provincial vote in January 1916 after a long campaign led by Nellie McClung and others. Saskatchewan and Alberta followed within months.", chapter:"Canada's History" },
  { q:"Which two provinces make up most of Canada's population?", options:["Manitoba and Saskatchewan", "Ontario and Quebec", "Alberta and British Columbia", "Nova Scotia and New Brunswick"], answer:1, explain:"Ontario and Quebec together hold well over half of all Canadians, which is why they dominate the House of Commons.", chapter:"Canada's Regions" },
  { q:"Which region is known as Canada's breadbasket?", options:["Central Canada", "The North", "The Prairie provinces", "The Atlantic provinces"], answer:2, explain:"Manitoba, Saskatchewan and Alberta grow most of Canada's wheat, canola and other grains on the flat, fertile prairie.", chapter:"Canada's Regions" },

  // ---------- Canada's history to Confederation (added 20 Aug 2026) ----------
  { q:"Before Europeans arrived, which Aboriginal people of the plains lived by following the bison herds?", options:["The Sioux","The Huron-Wendat","The Inuit","The Mi'kmaq"], answer:0, explain:"The Sioux were nomadic, moving with the bison (buffalo) herds that gave them food, clothing and shelter. Farming peoples such as the Huron-Wendat lived far to the east.", chapter:"Canada's History" },
  { q:"The Huron-Wendat of the Great Lakes region lived mainly by...", options:["mining and trading gold","farming and hunting","whaling in the Arctic","herding cattle"], answer:1, explain:"Like the Iroquois, the Huron-Wendat were farmers and hunters. They grew corn, beans and squash in villages near the Great Lakes.", chapter:"Canada's History" },
  { q:"How did the Aboriginal peoples of the West Coast preserve the fish they caught?", options:["By storing it in ice houses","By sealing it in clay jars","By drying and smoking it","By salting it in barrels"], answer:2, explain:"West Coast peoples dried and smoked fish, especially salmon, so it would keep through the winter. The rich Pacific fishery supported large permanent villages.", chapter:"Canada's History" },
  { q:"After Europeans arrived, what caused the deaths of very large numbers of Aboriginal people?", options:["A sudden change in the climate","The disappearance of the beaver","Floods along the St. Lawrence","Diseases brought from Europe"], answer:3, explain:"European diseases such as smallpox spread among peoples who had no immunity to them, and large Aboriginal populations died in the years after contact.", chapter:"Canada's History" },
  { q:"Aboriginal territorial rights in Canada were first guaranteed by which document?", options:["The Royal Proclamation of 1763","The Quebec Act of 1774","The Constitutional Act of 1791","The British North America Act of 1867"], answer:0, explain:"King George III issued the Royal Proclamation of 1763. It guaranteed territorial rights and set the basis for negotiating treaties with the newcomers.", chapter:"Who We Are" },
  { q:"Remains of a Norse settlement have been found at L'Anse aux Meadows. In which province is it?", options:["British Columbia","Newfoundland and Labrador","Nova Scotia","Quebec"], answer:1, explain:"L'Anse aux Meadows, on the northern tip of Newfoundland, is a World Heritage site and the only confirmed Norse settlement in North America.", chapter:"Canada's History" },
  { q:"John Cabot, who claimed Canada's Atlantic shore for England in 1497, had come to England from which country?", options:["Spain","The Netherlands","Italy","Portugal"], answer:2, explain:"Cabot was an Italian immigrant to England, and he was the first to draw a map of Canada's East Coast.", chapter:"Canada's History" },
  { q:"Jacques Cartier claimed the land he explored for which king of France?", options:["King Louis XIV","King Henry IV","King Louis XVI","King Francis I"], answer:3, explain:"Cartier made three voyages between 1534 and 1542 and claimed the land for King Francis I.", chapter:"Canada's History" },
  { q:"Cartier took the Iroquoian word 'kanata' to be the name of the land. By which decade was 'Canada' appearing on maps?", options:["The 1550s","The 1490s","The 1650s","The 1750s"], answer:0, explain:"By the 1550s the name Canada was appearing on maps of the region, about twenty years after Cartier first heard the word.", chapter:"Canada's History" },
  { q:"In 1604 Pierre de Monts and Samuel de Champlain founded the first European settlement north of Florida. Where did it end up?", options:["St. John's, Newfoundland","Port-Royal, in what is now Nova Scotia","Quebec City","Montreal"], answer:1, explain:"The settlement began on St. Croix Island and was moved to Port-Royal in Acadia, today's Nova Scotia. Champlain founded Quebec four years later.", chapter:"Canada's History" },
  { q:"Champlain allied the French colony with which Aboriginal peoples in their conflict with the Iroquois?", options:["The Sioux, Blackfoot and Mi'kmaq","The Haida, Salish and Nisga'a","The Algonquin, Montagnais and Huron","The Cree, Dene and Inuit"], answer:2, explain:"That alliance shaped the fur trade and drew the French into a long conflict with the Iroquois that lasted most of the century.", chapter:"Canada's History" },
  { q:"In what year did the French and the Iroquois finally make peace?", options:["1608","1763","1812","1701"], answer:3, explain:"The French and the Iroquois made peace in 1701, ending decades of warfare and opening the interior to trade.", chapter:"Canada's History" },
  { q:"Beaver pelts were shipped from Canada to Europe mainly to make what?", options:["Fashionable felt hats","Winter boots","Paint brushes","Ships' ropes"], answer:0, explain:"Beaver felt hats were the height of European fashion for about two centuries, and that demand drove the fur trade that built early Canada.", chapter:"Canada's History" },
  { q:"Which king granted the Hudson's Bay Company its trading rights in 1670?", options:["King William IV","King Charles II","King George III","King Henry VIII"], answer:1, explain:"King Charles II granted the company exclusive trading rights over all the land draining into Hudson Bay, an area covering much of what is now Canada.", chapter:"Canada's History" },
  { q:"Who were the coureurs des bois and the voyageurs?", options:["Priests who ran mission schools","Farmers who cleared land along the St. Lawrence","Traders who travelled the rivers by canoe deep into the interior","Soldiers who guarded the fortress of Quebec"], answer:2, explain:"These skilled canoe men carried trade goods inland and furs back out, living for months in the bush and forming close alliances with First Nations.", chapter:"Canada's History" },
  { q:"Which Montreal-based company was the Hudson's Bay Company's great rival until the two merged in 1821?", options:["The East India Company","The Canada Company","The Grand Trunk Company","The North West Company"], answer:3, explain:"Founded in Montreal in 1779, the North West Company competed fiercely for the western fur trade until the two companies joined in 1821.", chapter:"Canada's History" },
  { q:"What part did First Nations people play in the fur trade?", options:["They trapped and supplied most of the furs and guided the traders","They took no part in it","They bought furs from European farmers","They worked only in the shipyards"], answer:0, explain:"The trade was a partnership. First Nations people trapped, prepared and carried the pelts, and taught the newcomers how to travel and survive in the country.", chapter:"Canada's History" },
  { q:"What name was given to the settlement founded in 1642 that grew into Montreal?", options:["Port-Royal","Ville-Marie","Nouvelle-Orléans","Stadacona"], answer:1, explain:"Ville-Marie was founded in 1642 as a Catholic mission on the island of Montreal, led by Paul de Chomedey de Maisonneuve.", chapter:"Canada's History" },
  { q:"Who founded the Hôtel-Dieu, the first hospital in Montreal?", options:["Madeleine de Verchères","Laura Secord","Jeanne Mance","Marguerite Bourgeoys"], answer:2, explain:"Jeanne Mance sailed with the founders of Ville-Marie in 1642 and raised the money to open the Hôtel-Dieu, one of the oldest hospitals in North America.", chapter:"Canada's History" },
  { q:"Who were the filles du roi, or King's Daughters?", options:["The daughters of the King of France, sent to govern the colony","Nuns who were sent to teach in mission schools","Women who inherited seigneuries from their fathers","Young women whose passage to New France was paid by the King so the colony could grow"], answer:3, explain:"Between 1663 and 1673 King Louis XIV paid the way of about 800 young women and gave them dowries, because the colony had far more men than women.", chapter:"Canada's History" },
  { q:"Why were the farms of New France laid out as long, narrow strips?", options:["So that every farm touched the river, which was the main road","Because the land was too rocky to farm in squares","To make the fields easier to plough with oxen","Because the Church owned the land in between"], answer:0, explain:"Under the seigneurial system land was granted in long ribbons running back from the St. Lawrence, so each family had water frontage. You can still see the pattern from the air.", chapter:"Canada's History" },
  { q:"Jean Talon, Bishop Laval and Count Frontenac helped build a French empire that reached from Hudson Bay to where?", options:["The Caribbean islands","The Gulf of Mexico","Cape Horn","The Pacific Ocean"], answer:1, explain:"By the late 1600s French posts and claims stretched from Hudson Bay south to the Gulf of Mexico, though few French people ever settled that vast area.", chapter:"Canada's History" },
  { q:"During the Great Upheaval, roughly what share of the Acadians were deported from their homeland?", options:["About one quarter","Almost none","More than two thirds","About one in ten"], answer:2, explain:"Between 1755 and 1763, during the war between Britain and France, more than two thirds of the Acadians were deported. They survived the ordeal and kept their identity.", chapter:"Who We Are" },
  { q:"Acadians who eventually made their way to Louisiana became known there as...", options:["Creoles","Loyalists","Voyageurs","Cajuns"], answer:3, explain:"'Cajun' is a worn-down form of 'Acadien'. Deported Acadians were scattered around the Atlantic, and many later gathered in French-speaking Louisiana.", chapter:"Canada's History" },
  { q:"The 1759 Battle of the Plains of Abraham was part of which wider war?", options:["The Seven Years' War","The War of 1812","The American Revolution","The Napoleonic Wars"], answer:0, explain:"Britain and France fought the Seven Years' War around the world. The fall of Quebec in 1759 ended France's empire in North America.", chapter:"Canada's History" },
  { q:"What happened to the two commanders at the Battle of the Plains of Abraham?", options:["Both survived and signed a truce together","Both Wolfe and Montcalm died of their wounds","Both were taken prisoner","Wolfe was captured and Montcalm escaped"], answer:1, explain:"Brigadier James Wolfe of Britain and the Marquis de Montcalm of France were both fatally wounded in a battle that lasted well under an hour.", chapter:"Canada's History" },
  { q:"After the conquest, what did the British call the former French colony?", options:["New Britain","The Dominion of Canada","The Province of Quebec","Upper Canada"], answer:2, explain:"The British renamed it the Province of Quebec. Its French-speaking Catholic majority, the Canadiens, wanted to keep their way of life.", chapter:"Canada's History" },
  { q:"Which system of law did the Quebec Act of 1774 restore?", options:["Roman law for the whole colony","Aboriginal customary law","Scottish law","French civil law, while British criminal law stayed in place"], answer:3, explain:"The Quebec Act kept British criminal law but brought back French civil law, and it let Catholics practise their faith and hold public office. It is often called a constitutional foundation of Canada.", chapter:"Canada's History" },
  { q:"About how many Loyalists moved north to Nova Scotia and Quebec during and after the American Revolution?", options:["More than 40,000","About 400","About 4,000","About 400,000"], answer:0, explain:"More than 40,000 Loyalists came north rather than live in the new United States, and they reshaped the colonies that became Canada.", chapter:"Canada's History" },
  { q:"Which Mohawk leader brought thousands of Loyalist Mohawk north into Canada?", options:["Pontiac","Joseph Brant","Tecumseh","Big Bear"], answer:1, explain:"Joseph Brant, also known as Thayendanegea, led Mohawk allies of the Crown to new lands in what is now Ontario after the American Revolution.", chapter:"Canada's History" },
  { q:"Who were the Black Loyalists?", options:["Refugees who arrived from the Caribbean in the 1900s","Traders employed by the Hudson's Bay Company","About 3,000 Black people, free and enslaved, who came north with the Loyalists","Soldiers sent from Britain to garrison Halifax"], answer:2, explain:"Roughly 3,000 Black Loyalists came to Nova Scotia and New Brunswick in search of a better life. Many were freedmen, and the land they were promised often did not arrive.", chapter:"Canada's History" },
  { q:"In 1792 a group of Black Nova Scotians left Canada to help found which settlement in West Africa?", options:["Monrovia, Liberia","Accra, Ghana","Lagos, Nigeria","Freetown, Sierra Leone"], answer:3, explain:"Over a thousand Black Nova Scotians sailed for West Africa in 1792 and founded Freetown, today the capital of Sierra Leone.", chapter:"Canada's History" },
  { q:"Where was the first representative assembly in what is now Canada elected, in 1758?", options:["Halifax, Nova Scotia","Quebec City","Toronto","Charlottetown"], answer:0, explain:"Nova Scotia's assembly first met in Halifax in 1758. Prince Edward Island followed in 1773 and New Brunswick in 1785.", chapter:"Canada's History" },
  { q:"What did the Constitutional Act of 1791 give the people of Upper and Lower Canada for the first time?", options:["Their own currency","Legislative assemblies elected by the people","The right to elect their own governor","Free public schools"], answer:1, explain:"The Act created elected legislative assemblies in both Canadas, an early step towards the democracy Canadians have today. The name 'Canada' also became official that year.", chapter:"Canada's History" },
  { q:"Which Lieutenant Governor led Upper Canada to pass its 1793 law against slavery?", options:["Lord Elgin","Sir Isaac Brock","John Graves Simcoe","Lord Durham"], answer:2, explain:"Simcoe, a soldier and an opponent of slavery, pushed the measure through. It made Upper Canada one of the first places in the British Empire to act against slavery.", chapter:"Canada's History" },
  { q:"Who abolished slavery throughout the British Empire, including Canada, in 1833?", options:["The Parliament of Canada","The United States Congress","The Governor General","The British Parliament"], answer:3, explain:"The British Parliament had already banned the slave trade in 1807, and in 1833 it abolished slavery across the Empire. The law took effect the following year.", chapter:"Canada's History" },
  { q:"Which star did people escaping slavery in the United States follow on their way to Canada?", options:["The North Star","The Evening Star","The Southern Cross","Sirius"], answer:0, explain:"'Follow the North Star' meant walking north to freedom. Thousands of escaped slaves reached Canada, where slavery had already ended.", chapter:"Canada's History" },
  { q:"The Underground Railroad that brought escaped slaves to Canada was run mainly by whom?", options:["The Government of Canada","A Christian anti-slavery network","The British Army","The Hudson's Bay Company"], answer:1, explain:"It was a Christian anti-slavery network of guides and safe houses. It was not a railway at all, and the name came from its code words.", chapter:"Canada's History" },
  { q:"Which British general captured Detroit in 1812 and was killed defending Queenston Heights?", options:["Lieutenant-Colonel Charles de Salaberry","General James Wolfe","Major-General Sir Isaac Brock","Major-General Robert Ross"], answer:2, explain:"Brock's boldness at Detroit convinced many people that Canada could be defended. He died at Queenston Heights later in 1812, in a battle the Americans lost.", chapter:"Canada's History" },
  { q:"At which 1813 battle did a small, mostly French-Canadian force turn back a much larger American army?", options:["Queenston Heights","Vimy Ridge","Batoche","Châteauguay"], answer:3, explain:"Lieutenant-Colonel Charles de Salaberry and 460 soldiers, most of them Canadiens, stopped 4,000 American invaders at Châteauguay.", chapter:"Canada's History" },
  { q:"In 1813 American forces burned the public buildings of which town, now Canada's largest city?", options:["York","Kingston","Montreal","Halifax"], answer:0, explain:"American troops burned Government House and the Parliament Buildings at York, the capital of Upper Canada. York was renamed Toronto in 1834.", chapter:"Canada's History" },
  { q:"In 1814 British and Canadian forces burned the White House and other public buildings in which city?", options:["Philadelphia","Washington","New York","Boston"], answer:1, explain:"Major-General Robert Ross led the raid on Washington in reply to the burning of York. He was killed soon afterwards and is buried in Halifax with military honours.", chapter:"Canada's History" },
  { q:"What did the War of 1812 settle for Canada?", options:["Quebec was handed back to France","Britain gave up all its colonies in North America","The American invasions failed, and Canada remained separate from the United States","Canada became fully independent from Britain"], answer:2, explain:"By 1814 the American attempt at conquest had failed. The war helped fix the Canada-United States border and made sure Canada would develop as a separate country.", chapter:"Canada's History" },
  { q:"Where did the armed rebellions of 1837 and 1838 break out?", options:["In Halifax and Saint John","In Winnipeg and Regina","In Victoria and Vancouver","In the area outside Montreal and in Toronto"], answer:3, explain:"The rebels wanted faster political reform, but they did not have enough public support to succeed. British troops and Canadian volunteers put the risings down.", chapter:"Canada's History" },
  { q:"Who led the 1837 rebellions in Lower Canada and in Upper Canada?", options:["Louis-Joseph Papineau and William Lyon Mackenzie","Robert Baldwin and Louis-Hippolyte LaFontaine","Joseph Howe and Leonard Tilley","John A. Macdonald and George-Étienne Cartier"], answer:0, explain:"Papineau led the Patriotes in Lower Canada and Mackenzie, a Toronto newspaperman, led the rising in Upper Canada. Both fled into exile after they were defeated.", chapter:"Canada's History" },
  { q:"Who was sent from Britain to report on the causes of the 1837 and 1838 rebellions?", options:["Lord Strathcona","Lord Durham","Lord Elgin","Lord Nelson"], answer:1, explain:"Lord Durham was an English reformer sent out after the risings. His report on what he found shaped the next thirty years of politics in the two Canadas.", chapter:"Canada's History" },
  { q:"What did Lord Durham's report recommend?", options:["Joining the United States","Abolishing the elected assemblies","Uniting Upper and Lower Canada and granting responsible government","Returning Quebec to France"], answer:2, explain:"Durham urged union and responsible government. He also urged the Canadiens to give up their language and religion, advice they rejected and that was never carried out.", chapter:"Canada's History" },
  { q:"In 1840 Upper and Lower Canada were joined together into what?", options:["The Dominion of Canada","The Confederation of Canada","The Colony of New Britain","The Province of Canada"], answer:3, explain:"The union created the Province of Canada, which lasted until 1867, when it was divided again into Ontario and Quebec.", chapter:"Canada's History" },
  { q:"Which colony was the first in British North America to win full responsible government, in 1847 and 1848?", options:["Nova Scotia","Newfoundland","New Brunswick","Prince Edward Island"], answer:0, explain:"Nova Scotia led the way, and it did so peacefully, without a shot being fired. The united Province of Canada followed in 1848 and 1849.", chapter:"Canada's History" },
  { q:"Which Nova Scotia journalist and politician campaigned for responsible government?", options:["George Brown","Joseph Howe","Leonard Tilley","Charles Tupper"], answer:1, explain:"Howe used his newspaper and his seat in the assembly to argue that the government must answer to the elected members, and Nova Scotia won that fight in 1848.", chapter:"Canada's History" },
  { q:"Which two reformers led the fight for responsible government in the Province of Canada?", options:["Louis Riel and Gabriel Dumont","Joseph Howe and Sir Charles Tupper","Robert Baldwin and Sir Louis-Hippolyte LaFontaine","Sir John A. Macdonald and Sir George-Étienne Cartier"], answer:2, explain:"Baldwin from Canada West and LaFontaine from Canada East worked as partners across the language divide. LaFontaine became the first head of a responsible government in the Canadas in 1849.", chapter:"Canada's History" },
  { q:"Which governor brought responsible government to the united Province of Canada in 1848 and 1849?", options:["Lord Durham","Lord Selkirk","Lord Dorchester","Lord Elgin"], answer:3, explain:"Lord Elgin, encouraged by London, accepted that ministers must keep the support of the elected assembly. A mob burned the parliament in Montreal in protest, and he did not back down.", chapter:"Canada's History" },
  { q:"In which city did the first conference on Confederation meet, in September 1864?", options:["Charlottetown","Quebec City","Ottawa","London"], answer:0, explain:"Delegates from the Province of Canada travelled to Charlottetown, Prince Edward Island, and joined the talks there. That is why the city calls itself the Birthplace of Confederation.", chapter:"Canada's History" },
  { q:"What had the Maritime delegates originally planned to discuss at Charlottetown in 1864?", options:["An end to the fur trade","A union of the Maritime colonies only","A canal to Hudson Bay","Joining the United States"], answer:1, explain:"They met to talk about a Maritime union, but delegates from the Province of Canada asked to join them and put the larger idea of a country on the table.", chapter:"Canada's History" },
  { q:"Which 1864 conference produced the 72 Resolutions that became the plan for Confederation?", options:["The London Conference","The Halifax Conference","The Quebec Conference","The Charlottetown Conference"], answer:2, explain:"Meeting at Quebec City in October 1864, the delegates set out 72 Resolutions. They became the basis of the British North America Act.", chapter:"Canada's History" },
  { q:"Who suggested the title 'Dominion of Canada'?", options:["Sir John A. Macdonald","Sir George-Étienne Cartier","Sir Charles Tupper","Sir Leonard Tilley"], answer:3, explain:"Tilley, a Father of Confederation from New Brunswick, took the word from Psalm 72 in the Bible, which speaks of dominion from sea to sea.", chapter:"Canada's History" },
  { q:"Which two Maritime colonies joined the Province of Canada in the new Dominion in 1867?", options:["Nova Scotia and New Brunswick","Prince Edward Island and Newfoundland","Manitoba and British Columbia","Yukon and the Northwest Territories"], answer:0, explain:"Nova Scotia and New Brunswick came in at Confederation. Prince Edward Island, which had hosted the first conference, did not join until 1873.", chapter:"Canada's History" },
  { q:"Which Montreal lawyer was Sir John A. Macdonald's closest partner and led Quebec into Confederation?", options:["Joseph Howe","Sir George-Étienne Cartier","Sir Wilfrid Laurier","Sir Leonard Tilley"], answer:1, explain:"Cartier was the key architect of Confederation in Quebec. He later helped bring Manitoba, British Columbia and the North-West Territories into Canada.", chapter:"Canada's History" },
  { q:"In which country was Sir John A. Macdonald, Canada's first Prime Minister, born?", options:["England","France","Scotland","Ireland"], answer:2, explain:"Macdonald was born in Scotland in 1815 and came to Upper Canada as a boy. He became a lawyer in Kingston, Ontario.", chapter:"Canada's History" },
  { q:"Most French-speaking Quebecers today descend from roughly how many French settlers of the 1600s and 1700s?", options:["About 850","About 85,000","About 850,000","About 8,500"], answer:3, explain:"New France was never heavily settled. About 8,500 French colonists are the ancestors of most Quebecers today, and their descendants now number in the millions.", chapter:"Who We Are" },


  // ---------- added 3 September 2026: ten more for every chapter ----------
  { q:"How long must you have been physically in Canada before you can apply for citizenship?", options:["1,095 days in the last 5 years","365 days in the last 2 years","2,000 days in the last 10 years","There is no time requirement"], answer:0, explain:"You must have been physically present in Canada for at least 1,095 days — three years — during the five years before you apply.", chapter:"About the Test" },
  { q:"Which ages are required to take the citizenship knowledge test?", options:["Everyone, at any age","18 to 54","16 to 65","Only people over 30"], answer:1, explain:"Applicants aged 18 to 54 must take the knowledge test and meet the language requirement. Children and older applicants do not.", chapter:"About the Test" },
  { q:"In which languages can you take the citizenship test?", options:["English or French","Any language you choose","English only","French only"], answer:0, explain:"The test is given in English or French, Canada's two official languages. You choose which one.", chapter:"About the Test" },
  { q:"What must you take part in before you officially become a citizen?", options:["A job interview","A citizenship ceremony where you take the Oath","A public vote","A medical examination"], answer:1, explain:"Applicants aged 14 and over attend a citizenship ceremony and take the Oath of Citizenship. That is the moment you become a citizen.", chapter:"About the Test" },
  { q:"What status must you already hold to apply for Canadian citizenship?", options:["Visitor","Student","Permanent resident","Work permit holder"], answer:2, explain:"You must be a permanent resident of Canada, and your status must not be in question, before you can apply.", chapter:"About the Test" },
  { q:"What happens if you do not pass the written citizenship test the first time?", options:["Your application is closed forever","You must wait ten years","You are usually given another chance","You automatically become a citizen anyway"], answer:2, explain:"Failing once is not the end. Applicants are normally offered a second test, and after that an interview with a citizenship official.", chapter:"About the Test" },
  { q:"Which subjects does the citizenship test cover?", options:["Only Canadian history","Rights, responsibilities, history, government, geography and symbols","Only the names of the provinces","Only sport and culture"], answer:1, explain:"The test draws on the whole Discover Canada guide: rights and responsibilities, history, government, geography, the economy and Canadian symbols.", chapter:"About the Test" },
  { q:"Is this practice website an official Government of Canada test?", options:["No — it is unofficial practice only","Yes, the result is sent to the government","Yes, it replaces the real test","Yes, if you score 20 out of 20"], answer:0, explain:"This site is unofficial and has no connection to the Government of Canada. No result is recorded or sent anywhere. Study the official Discover Canada guide as well.", chapter:"About the Test" },
  { q:"Roughly how long do you have for each question in the real test?", options:["About ten seconds","A little over two minutes","About ten minutes","As long as you like"], answer:1, explain:"Forty-five minutes divided by twenty questions is a little over two minutes each. That is comfortable if you have studied.", chapter:"About the Test" },
  { q:"Where can you get the official Discover Canada study guide?", options:["It must be bought from a bookshop","Free from the Government of Canada","Only from a lawyer","It is not available to the public"], answer:1, explain:"Discover Canada is published free by the Government of Canada, online and in other formats. You never need to pay for it.", chapter:"About the Test" },
  { q:"Which right allows a citizen to live and work anywhere in Canada?", options:["Mobility rights","Language rights","Legal rights","Equality rights"], answer:0, explain:"Mobility rights let citizens live and seek work anywhere in Canada, enter and leave the country, and apply for a passport.", chapter:"Rights and Responsibilities" },
  { q:"Serving on a jury when you are called is best described as…", options:["An optional favour","A responsibility of citizenship","A paid career","Something only lawyers do"], answer:1, explain:"Serving on a jury is a responsibility of citizenship. The justice system depends on ordinary people agreeing to do it.", chapter:"Rights and Responsibilities" },
  { q:"Which of these is a responsibility rather than a right?", options:["Voting in elections","Paying your taxes","Speaking freely","Practising your religion"], answer:1, explain:"Paying taxes on income and on things you buy is a responsibility. Voting is both a right and a responsibility, but paying tax is squarely a duty.", chapter:"Rights and Responsibilities" },
  { q:"Which historic English document is one of the roots of Canadian law?", options:["The Treaty of Paris","Magna Carta","The Statute of Westminster","The Quebec Act"], answer:1, explain:"Magna Carta of 1215, the Great Charter of Freedoms, is one of the historic roots of the rights Canadians hold today.", chapter:"Rights and Responsibilities" },
  { q:"Which of these is a fundamental freedom protected by the Charter?", options:["Freedom of peaceful assembly","Freedom from paying tax","Freedom to ignore the courts","Freedom to carry any weapon"], answer:0, explain:"Freedom of peaceful assembly is one of the four fundamental freedoms, along with conscience and religion, thought and expression, and association.", chapter:"Rights and Responsibilities" },
  { q:"What does the Charter say about men and women?", options:["Men have more rights","Women have more rights","They are equal under the law","It does not mention them"], answer:2, explain:"Equality of women and men under the law is a fundamental principle in Canada. Practices that go against it are not accepted.", chapter:"Rights and Responsibilities" },
  { q:"Learning one of Canada's official languages is described in the guide as…", options:["Forbidden for newcomers","A responsibility that helps you take part in Canadian life","Only useful for government workers","A legal requirement for children"], answer:1, explain:"Learning English or French opens work, study and community life. The guide treats it as a responsibility that helps you belong.", chapter:"Rights and Responsibilities" },
  { q:"Which right belongs to citizens but not to permanent residents?", options:["The right to work","The right to vote in a federal election","The right to a fair trial","The right to attend school"], answer:1, explain:"Voting and running for office in federal elections are rights of citizens. Permanent residents share most other rights but not these.", chapter:"Rights and Responsibilities" },
  { q:"What does the Charter protect about the use of English and French?", options:["Only English may be used in Parliament","The right to use either in Parliament and federal courts","Neither may be used in court","Provinces must ban one of them"], answer:1, explain:"Official language rights let people use English or French in Parliament and in federal courts, and receive federal services in either.", chapter:"Rights and Responsibilities" },
  { q:"Which action best shows the responsibility of protecting Canada's heritage and environment?", options:["Leaving rubbish in a national park","Keeping public places clean and safe","Building wherever you like","Ignoring recycling rules"], answer:1, explain:"Caring for the land, the water and public places is listed in the guide as a responsibility every Canadian shares.", chapter:"Rights and Responsibilities" },
  { q:"Which three groups make up the Aboriginal peoples of Canada?", options:["First Nations, Inuit and Métis","Settlers, farmers and traders","English, French and Irish","Loyalists, Acadians and Quebecers"], answer:0, explain:"The Constitution recognizes three Aboriginal peoples: First Nations, Inuit and Métis, each with their own histories, languages and cultures.", chapter:"Who We Are" },
  { q:"Who are the Métis?", options:["Recent immigrants from Europe","People of mixed Aboriginal and European ancestry","Another name for the Inuit","A political party"], answer:1, explain:"The Métis are a distinct people of mixed Aboriginal and European ancestry, most of whom live in the Prairie provinces. Many speak Michif.", chapter:"Who We Are" },
  { q:"Where do most Inuit live in Canada?", options:["Southern Ontario","The Arctic","Vancouver Island","The Prairies"], answer:1, explain:"Inuit means 'the people' in Inuktitut. Most Inuit live in the Arctic, across the northern parts of Canada.", chapter:"Who We Are" },
  { q:"What word describes the mixing of many cultures within one Canadian society?", options:["Isolation","Multiculturalism","Separation","Assimilation"], answer:1, explain:"Canada's multicultural character means people keep their heritage while sharing Canadian values and one society.", chapter:"Who We Are" },
  { q:"Which two languages are Canada's official languages?", options:["English and French","English and Spanish","French and Inuktitut","English and Mandarin"], answer:0, explain:"English and French have equal status in Parliament, in federal courts and in federal government services.", chapter:"Who We Are" },
  { q:"Roughly what share of Canadians speak French as a first language?", options:["About one in five","About half","About one in fifty","Almost none"], answer:0, explain:"Roughly one Canadian in five speaks French as a first language, and most of them live in Quebec, with communities across the country.", chapter:"Who We Are" },
  { q:"Who are the Acadians?", options:["Early Chinese settlers","Descendants of French colonists in the Atlantic region","A First Nation of the Prairies","British soldiers who stayed"], answer:1, explain:"The Acadians are the descendants of French colonists who settled in what is now the Atlantic provinces from the 1600s onwards.", chapter:"Who We Are" },
  { q:"What was the Underground Railroad?", options:["Canada's first subway system","A network that helped enslaved people reach freedom in Canada","A mining tunnel in Alberta","A secret military road"], answer:1, explain:"The Underground Railroad was a secret network that helped thousands of enslaved people escape the United States and reach freedom in Canada.", chapter:"Who We Are" },
  { q:"What is the name for people who came to Canada from another country to live?", options:["Tourists","Immigrants","Visitors","Delegates"], answer:1, explain:"Immigrants come to Canada to settle permanently. Roughly one in five Canadians was born outside the country.", chapter:"Who We Are" },
  { q:"What is a treaty between the Crown and First Nations?", options:["A shopping agreement","A solemn agreement setting out rights and obligations on both sides","A temporary loan","A form of tax"], answer:1, explain:"Treaties are solemn agreements that set out ongoing rights and obligations for both the Crown and First Nations. The Constitution protects treaty rights.", chapter:"Who We Are" },
  { q:"Which European people reached the coast of Newfoundland about 1,000 years ago?", options:["The Vikings","The Romans","The Spanish","The Dutch"], answer:0, explain:"Vikings from Iceland and Greenland reached the coast of Newfoundland about 1,000 years ago. Their settlement at L'Anse aux Meadows is a World Heritage site.", chapter:"Canada's History" },
  { q:"Where does the name 'Canada' come from?", options:["A French word for river","Kanata, an Iroquoian word meaning village or settlement","The name of a British king","A Latin word for north"], answer:1, explain:"Jacques Cartier heard the Iroquoian word 'kanata', meaning village or settlement, and the name came to be used for the whole country.", chapter:"Canada's History" },
  { q:"Who founded Quebec City in 1608?", options:["Samuel de Champlain","John Cabot","Henry Hudson","Sir John A. Macdonald"], answer:0, explain:"Samuel de Champlain built a fortress at what is now Quebec City in 1608, beginning permanent French settlement in North America.", chapter:"Canada's History" },
  { q:"Who were the Loyalists?", options:["French soldiers who stayed after 1759","Settlers who moved north to remain under the British Crown","The first Members of Parliament","Fur traders from Russia"], answer:1, explain:"After the American Revolution, about 40,000 Loyalists moved north to settle in Nova Scotia, New Brunswick, Quebec and Ontario rather than live in the new republic.", chapter:"Canada's History" },
  { q:"What was the significance of the Battle of Vimy Ridge in 1917?", options:["It ended the fur trade","All four Canadian divisions fought together and won a hard victory","It was Canada's first naval battle","It created the province of Alberta"], answer:1, explain:"At Vimy Ridge in April 1917 all four Canadian divisions fought together for the first time and took a position others had failed to take. Canadians still mark it every April 9.", chapter:"Canada's History" },
  { q:"Which province was the last to join Confederation, in 1949?", options:["Alberta","Newfoundland and Labrador","British Columbia","Prince Edward Island"], answer:1, explain:"Newfoundland and Labrador joined Canada in 1949, the last province to do so.", chapter:"Canada's History" },
  { q:"What did the Canadian Pacific Railway, completed in 1885, achieve?", options:["It linked Canada from coast to coast","It connected Canada to Mexico","It carried only mail","It was never finished"], answer:0, explain:"The Canadian Pacific Railway linked eastern Canada to the Pacific coast, fulfilling a promise made to British Columbia. Thousands of Chinese labourers helped build it in dangerous conditions.", chapter:"Canada's History" },
  { q:"In which war was Canada successfully defended against invasion from the United States?", options:["The War of 1812","The First World War","The Seven Years' War","The Second World War"], answer:0, explain:"In 1812 the United States invaded, but British soldiers, Canadian volunteers and First Nations allies turned the invasion back. Laura Secord famously walked 30 kilometres to warn of an attack.", chapter:"Canada's History" },
  { q:"What was the Underground Railroad's destination for many who used it?", options:["Mexico","Canada","Cuba","Iceland"], answer:1, explain:"Slavery was abolished throughout the British Empire in 1833, so Canada became the destination for thousands escaping slavery in the United States.", chapter:"Canada's History" },
  { q:"In which year did Canada bring its Constitution home and add the Charter?", options:["1867","1931","1982","1999"], answer:2, explain:"In 1982 Canada patriated its Constitution, meaning it could be amended in Canada, and the Canadian Charter of Rights and Freedoms was added to it.", chapter:"Canada's History" },
  { q:"Which four provinces make up Atlantic Canada?", options:["Newfoundland and Labrador, Prince Edward Island, Nova Scotia, New Brunswick","Quebec, Ontario, Manitoba, Saskatchewan","Alberta, British Columbia, Yukon, Nunavut","Ontario, Quebec, Nova Scotia, Alberta"], answer:0, explain:"Atlantic Canada is made up of Newfoundland and Labrador, Prince Edward Island, Nova Scotia and New Brunswick.", chapter:"Canada's Regions" },
  { q:"Which two provinces are known as Central Canada?", options:["Manitoba and Saskatchewan","Ontario and Quebec","Alberta and British Columbia","Nova Scotia and New Brunswick"], answer:1, explain:"Ontario and Quebec are Central Canada. More than half of Canadians live there, and much of the country's manufacturing is based there.", chapter:"Canada's Regions" },
  { q:"Which bay on Canada's Atlantic coast has the highest tides in the world?", options:["The Bay of Fundy","Hudson Bay","Georgian Bay","Baffin Bay"], answer:0, explain:"The Bay of Fundy, between New Brunswick and Nova Scotia, has the highest tides in the world. The water can rise and fall by more than fifteen metres in a single day.", chapter:"Canada's Regions" },
  { q:"Which ocean lies on British Columbia's coast?", options:["The Atlantic Ocean","The Pacific Ocean","The Arctic Ocean","The Indian Ocean"], answer:1, explain:"British Columbia is Canada's Pacific province. Its port at Vancouver is Canada's largest and busiest.", chapter:"Canada's Regions" },
  { q:"Which three territories make up Canada's North?", options:["Yukon, Northwest Territories and Nunavut","Yukon, Alberta and Nunavut","Nunavut, Labrador and Yukon","Northwest Territories, Manitoba and Yukon"], answer:0, explain:"Yukon, the Northwest Territories and Nunavut make up about a third of Canada's land but hold only a small share of its people.", chapter:"Canada's Regions" },
  { q:"In which year was Nunavut created?", options:["1949","1982","1999","2005"], answer:2, explain:"Nunavut was created in 1999 from the eastern part of the Northwest Territories. Its name means 'our land' in Inuktitut.", chapter:"Canada's Regions" },
  { q:"Which city is the capital of Canada?", options:["Toronto","Ottawa","Montreal","Vancouver"], answer:1, explain:"Ottawa, in Ontario on the Ottawa River, was chosen as the capital in 1857 and is where Parliament sits.", chapter:"Canada's Regions" },
  { q:"Which is Canada's largest province by area?", options:["Quebec","Ontario","British Columbia","Alberta"], answer:0, explain:"Quebec is the largest province by area. Only the territory of Nunavut covers more ground.", chapter:"Canada's Regions" },
  { q:"Which province is the only officially bilingual province?", options:["Quebec","Ontario","New Brunswick","Manitoba"], answer:2, explain:"New Brunswick is Canada's only officially bilingual province, with about a third of its people French-speaking.", chapter:"Canada's Regions" },
  { q:"Which is Canada's smallest province by area?", options:["Nova Scotia","Prince Edward Island","New Brunswick","Newfoundland and Labrador"], answer:1, explain:"Prince Edward Island is the smallest province. It is known for its red soil, its potatoes and as the birthplace of Confederation.", chapter:"Canada's Regions" },
  { q:"What does the word 'the Crown' mean in Canadian government?", options:["The state itself, in whose name government, courts and police act","A jewelled hat kept in Ottawa","The Prime Minister's office","A committee of the Senate"], answer:0, explain:"The Crown stands for the state itself. Governments, courts, police and the armed forces all act in its name, which is why land can be called Crown land and a prosecutor acts for the Crown.", chapter:"How Canadians Govern Themselves" },
  { q:"How are senators chosen?", options:["They are elected by voters","They are appointed","They inherit the seat","They are chosen by the provinces alone"], answer:1, explain:"Senators are appointed rather than elected, and the Senate is designed to give the regions of Canada a voice in reviewing laws.", chapter:"How Canadians Govern Themselves" },
  { q:"What are the three levels of government in Canada?", options:["Federal, provincial or territorial, and municipal","Royal, national and local","Federal, judicial and military","National, regional and family"], answer:0, explain:"Canada has federal, provincial or territorial, and municipal levels of government, each with its own responsibilities.", chapter:"How Canadians Govern Themselves" },
  { q:"What usually happens if the government loses a confidence vote in the House of Commons?", options:["The government must resign and an election is usually called","Nothing changes","The Senate takes over","The vote is simply repeated"], answer:0, explain:"A government must keep the confidence of the House of Commons. If it loses a confidence vote it must resign, and an election normally follows.", chapter:"How Canadians Govern Themselves" },
  { q:"What is the head of a provincial government called?", options:["The Premier","The Governor","The President","The Speaker"], answer:0, explain:"The leader of the party with the most seats in a provincial legislature becomes the Premier.", chapter:"How Canadians Govern Themselves" },
  { q:"What kind of state is Canada, in terms of how power is shared?", options:["A federal state","A single unified state","A republic","A city state"], answer:0, explain:"Canada is a federal state: some powers belong to the federal Parliament and others to the provincial legislatures.", chapter:"How Canadians Govern Themselves" },
  { q:"Which level of government usually looks after local police, snow clearing and libraries?", options:["Federal","Provincial","Municipal","None of them"], answer:2, explain:"Municipal government handles local services such as snow clearing, libraries, water, and often local policing and fire services.", chapter:"How Canadians Govern Themselves" },
  { q:"Which level of government is responsible for national defence?", options:["Federal","Provincial","Municipal","Shared with the provinces"], answer:0, explain:"National defence, foreign policy, citizenship, criminal law and currency are federal responsibilities.", chapter:"How Canadians Govern Themselves" },
  { q:"What is a bill called once it has been passed and given Royal Assent?", options:["A motion","A law, or Act","A petition","A treaty"], answer:1, explain:"A bill must pass the House of Commons and the Senate and receive Royal Assent before it becomes a law.", chapter:"How Canadians Govern Themselves" },
  { q:"What is Canada's system of government called?", options:["A constitutional monarchy and parliamentary democracy","An absolute monarchy","A direct democracy","A military government"], answer:0, explain:"Canada is a constitutional monarchy, a parliamentary democracy and a federal state, all three at once.", chapter:"How Canadians Govern Themselves" },
  { q:"In which year did the maple leaf flag first fly over Canada?", options:["1867","1931","1965","1982"], answer:2, explain:"The red and white maple leaf flag was raised for the first time on 15 February 1965. That day is now National Flag of Canada Day.", chapter:"Canadian Symbols" },
  { q:"What does Canada's motto 'A Mari Usque Ad Mare' mean?", options:["Strong and free","From sea to sea","Peace and order","True north"], answer:1, explain:"The Latin motto on Canada's Coat of Arms means 'from sea to sea'.", chapter:"Canadian Symbols" },
  { q:"In which year did 'O Canada' officially become the national anthem?", options:["1867","1965","1980","1999"], answer:2, explain:"'O Canada' was first sung in 1880 but only became the official national anthem on 1 July 1980.", chapter:"Canadian Symbols" },
  { q:"What are Canada's two official national sports?", options:["Ice hockey and lacrosse","Hockey and curling","Football and baseball","Skiing and skating"], answer:0, explain:"By law, ice hockey is Canada's national winter sport and lacrosse its national summer sport. Lacrosse comes from Indigenous peoples.", chapter:"Canadian Symbols" },
  { q:"Which animal became an official emblem of Canada in 1975?", options:["The moose","The beaver","The polar bear","The loon"], answer:1, explain:"The beaver was made an official emblem of Canada in 1975. It was central to the fur trade that shaped the country's early economy.", chapter:"Canadian Symbols" },
  { q:"Which holiday honours the Sovereign and is held on the Monday before 25 May?", options:["Canada Day","Victoria Day","Labour Day","Remembrance Day"], answer:1, explain:"Victoria Day falls on the Monday before 25 May and is celebrated as the Sovereign's birthday in Canada.", chapter:"Canadian Symbols" },
  { q:"On what date do Canadians observe Remembrance Day?", options:["1 July","11 November","25 December","1 January"], answer:1, explain:"Remembrance Day is 11 November. Canadians wear a poppy and pause at 11 a.m. to honour those who served and died.", chapter:"Canadian Symbols" },
  { q:"Which tower stands at the centre of the Parliament Buildings in Ottawa?", options:["The Peace Tower","The CN Tower","The Clock Tower","The Maple Tower"], answer:0, explain:"The Peace Tower stands at the centre of the Centre Block on Parliament Hill and holds the Books of Remembrance.", chapter:"Canadian Symbols" },
  { q:"What is an inukshuk?", options:["A figure built of stones, used by Inuit as a marker","A traditional Inuit boat","A winter festival in Quebec","A type of northern bird"], answer:0, explain:"An inukshuk is a figure built of stacked stones. Inuit used them across the Arctic to mark a route, a good hunting place or a cache of food, and today it is recognised across Canada.", chapter:"Canadian Symbols" },
  { q:"What is the Royal Anthem of Canada?", options:["O Canada","God Save the King","The Maple Leaf Forever","Land of Hope and Glory"], answer:1, explain:"'God Save the King' is the Royal Anthem, played in the presence of the Sovereign or a member of the Royal Family. 'O Canada' is the national anthem.", chapter:"Canadian Symbols" },
  { q:"What is the longest a House of Commons may sit before an election must be held?", options:["Two years","Five years","Ten years","There is no limit"], answer:1, explain:"The Charter says no House of Commons may continue for longer than five years, except in a real emergency. In practice elections are usually held sooner.", chapter:"Federal Elections" },
  { q:"What is an electoral district also called?", options:["A riding","A province","A ward","A county council"], answer:0, explain:"Canada is divided into electoral districts, commonly called ridings. Each one elects a single Member of Parliament.", chapter:"Federal Elections" },
  { q:"Who wins the seat in a Canadian federal riding?", options:["The candidate with the most votes","The candidate with more than half the votes","The oldest candidate","The candidate chosen by the Senate"], answer:0, explain:"The candidate with the most votes wins the riding, even without more than half. This is called first past the post.", chapter:"Federal Elections" },
  { q:"What is the Official Opposition?", options:["The party with the second largest number of seats","Any party that dislikes the government","A group of senators","The party that won the most votes but no seats"], answer:0, explain:"The party with the second largest number of seats becomes the Official Opposition. Its job is to question the government and offer an alternative.", chapter:"Federal Elections" },
  { q:"What does it mean that Canadian elections use a secret ballot?", options:["Nobody may know how you voted","Only the government sees the result","Votes are never counted","You must tell an official your choice"], answer:0, explain:"No one has the right to watch you vote or to demand to know how you voted. That protection is a foundation of a free election.", chapter:"Federal Elections" },
  { q:"What is the voter information card sent to electors used for?", options:["It tells you where and when to vote","It is your ballot paper","It is a tax bill","It proves you voted"], answer:0, explain:"The card confirms you are on the voters list and tells you where and when to vote. You still need identification at the polling station.", chapter:"Federal Elections" },
  { q:"Which of these may vote in a Canadian federal election?", options:["A citizen aged 18 or over on election day","Any resident of Canada","A visitor with a valid passport","Anyone aged 16 or over"], answer:0, explain:"To vote federally you must be a Canadian citizen, at least 18 years old on election day, and on the voters list.", chapter:"Federal Elections" },
  { q:"What can you do if you cannot vote on election day itself?", options:["Vote at an advance poll or by special ballot","Ask a friend to vote for you","Vote twice next time","Nothing can be done"], answer:0, explain:"Advance polls open before election day, and a special ballot lets you vote by mail or at an Elections Canada office.", chapter:"Federal Elections" },
  { q:"Must a candidate belong to a political party to run for Parliament?", options:["No — a candidate may run as an independent","Yes, always","Only in Quebec","Only if they have never voted"], answer:0, explain:"Candidates may run for a party or as independents. Voters choose a person to represent their riding.", chapter:"Federal Elections" },
  { q:"What is a scrutineer at a polling station?", options:["Someone who represents a candidate and watches that the count is fair","The person who prints the ballots","A police officer guarding the door","A voter who has already voted twice"], answer:0, explain:"Candidates may send scrutineers to watch the voting and the count. Having rival candidates watch the same count is one of the plain, practical reasons Canadians can trust the result.", chapter:"Federal Elections" },
  { q:"Which sector of the economy employs the largest share of Canadians?", options:["Service industries","Farming","Fishing","Mining"], answer:0, explain:"Service industries — health care, education, retail, banking, transport and more — employ about three in four working Canadians.", chapter:"Canada's Economy" },
  { q:"Who is Canada's largest trading partner?", options:["The United States","China","The United Kingdom","Mexico"], answer:0, explain:"The United States is by far Canada's largest trading partner. The two countries share the longest undefended border in the world.", chapter:"Canada's Economy" },
  { q:"Which three broad types of industry does the guide describe in Canada's economy?", options:["Service, manufacturing and natural resources","Farming, fishing and forestry","Banking, tourism and sport","Oil, gas and coal"], answer:0, explain:"Canada's economy is usually described in three parts: service industries, manufacturing industries, and natural resources.", chapter:"Canada's Economy" },
  { q:"Which of these is a major Canadian natural resource export?", options:["Oil, timber and grain","Coffee and cocoa","Silk and spices","Rubber and bananas"], answer:0, explain:"Canada is a leading exporter of energy, forest products, minerals and agricultural products such as wheat and canola.", chapter:"Canada's Economy" },
  { q:"What is a trading nation?", options:["A country whose prosperity depends on selling to and buying from other countries","A country that refuses to trade","A country with no industry","A country that only trades with itself"], answer:0, explain:"Canada has always been a trading nation. A large share of what Canadians produce is sold abroad, and trade supports millions of jobs.", chapter:"Canada's Economy" },
  { q:"Which industry grew from the earliest European trade with Indigenous peoples?", options:["The fur trade","The steel industry","The airline industry","The film industry"], answer:0, explain:"The fur trade was the foundation of the early Canadian economy and depended on Indigenous knowledge, routes and labour.", chapter:"Canada's Economy" },
  { q:"What must most working Canadians file each year?", options:["An income tax return","A voting form","A travel report","Nothing at all"], answer:0, explain:"Filing an income tax return is a legal responsibility for most people who earn money in Canada. Taxes pay for roads, schools and health care.", chapter:"Canada's Economy" },
  { q:"Which Canadian region is best known for wheat and canola farming?", options:["The Prairies","The Atlantic provinces","The territories","Vancouver Island"], answer:0, explain:"The Prairie provinces grow much of Canada's grain, and Canada is one of the world's largest wheat exporters.", chapter:"Canada's Economy" },
  { q:"What is a free trade agreement?", options:["An agreement between countries to reduce or remove tariffs on goods","A promise to give goods away","A ban on all imports","A tax on Canadian workers"], answer:0, explain:"A free trade agreement lowers or removes tariffs so goods move more cheaply between countries. Canada's trade with the United States is by far its largest.", chapter:"Canada's Economy" },
  { q:"Why is the St. Lawrence Seaway important to Canada's economy?", options:["It lets ocean ships reach the Great Lakes","It is Canada's longest railway","It is a national park","It connects Canada to Europe by road"], answer:0, explain:"The St. Lawrence Seaway allows ocean-going ships to sail from the Atlantic deep into the Great Lakes, carrying grain, ore and manufactured goods.", chapter:"Canada's Economy" },
  { q:"In which year did Canada adopt an official policy of multiculturalism?", options:["1971","1867","1949","1999"], answer:0, explain:"Canada adopted an official multiculturalism policy in 1971, the first country in the world to do so.", chapter:"Modern Canada" },
  { q:"What is meant by Canada's system of universal health care?", options:["Basic medical care is available to residents without paying at the point of care","All medicine is free everywhere in the world","Only citizens over 65 receive care","Health care is run entirely by the federal government"], answer:0, explain:"Provinces and territories deliver health care, funded largely through taxes, so residents receive basic medical care without paying at the point of care.", chapter:"Modern Canada" },
  { q:"What role has Canada often played in United Nations missions abroad?", options:["Peacekeeping","Colonising new territory","Selling weapons only","Refusing to take part"], answer:0, explain:"Canadians have served in peacekeeping missions around the world, a tradition that grew out of Canada's role at the United Nations.", chapter:"Modern Canada" },
  { q:"What were residential schools?", options:["Schools that separated Indigenous children from their families and cultures","Boarding schools for wealthy families","Schools built for new immigrants","Universities in the North"], answer:0, explain:"Indigenous children were taken from their families and sent to residential schools, where they were forbidden to speak their languages. The Government of Canada apologised in 2008.", chapter:"Modern Canada" },
  { q:"Which Canadian discovery has saved millions of lives since the 1920s?", options:["Insulin","Penicillin","Aspirin","The X-ray"], answer:0, explain:"Insulin, the treatment for diabetes, was discovered in Toronto in 1921 by Frederick Banting and Charles Best.", chapter:"Modern Canada" },
  { q:"What is the Canadarm?", options:["A robotic arm built in Canada for use in space","A Canadian river","A type of aircraft","A hockey trophy"], answer:0, explain:"The Canadarm is a robotic arm designed and built in Canada, used on the space shuttle and later on the International Space Station.", chapter:"Modern Canada" },
  { q:"What did the Truth and Reconciliation Commission examine?", options:["The history and effects of residential schools","The price of housing","The results of an election","Trade with the United States"], answer:0, explain:"The Commission heard from thousands of survivors and documented what happened in residential schools, publishing Calls to Action for the country.", chapter:"Modern Canada" },
  { q:"Which group of countries does Canada belong to alongside the United States, the United Kingdom, France, Germany, Italy and Japan?", options:["The G7","The Commonwealth alone","The European Union","The African Union"], answer:0, explain:"Canada is a member of the G7 group of major economies, and also of the United Nations, NATO, the Commonwealth and la Francophonie.", chapter:"Modern Canada" },
  { q:"Roughly how many Canadians were born outside Canada?", options:["About one in five","About one in a hundred","Almost none","More than half"], answer:0, explain:"About one Canadian in five was born in another country, one of the highest shares among major nations.", chapter:"Modern Canada" },
  { q:"Which organisation for defence does Canada belong to with the United States and European allies?", options:["NATO","OPEC","ASEAN","The Arctic Council only"], answer:0, explain:"Canada was a founding member of NATO in 1949 and also works with the United States in NORAD to defend North American airspace.", chapter:"Modern Canada" },
  { q:"What does the rule of law mean?", options:["Everyone, including governments, must obey the law","The police may write new laws","Laws apply only to ordinary people","The richest person decides"], answer:0, explain:"Under the rule of law nobody is above the law — not a citizen, not a company, not a government or its leaders.", chapter:"The Justice System" },
  { q:"What does presumption of innocence mean?", options:["You are considered innocent until proven guilty","You must prove you are innocent","Only the accused may speak in court","A trial is not needed"], answer:0, explain:"Anyone charged with an offence is presumed innocent until proven guilty. The burden of proof rests on the prosecution, not the accused.", chapter:"The Justice System" },
  { q:"What is habeas corpus?", options:["The right to challenge unlawful detention","The right to own property","The right to travel abroad","The right to a free lawyer for life"], answer:0, explain:"Habeas corpus is the ancient right to challenge being held by the state, so that a court can decide whether the detention is lawful.", chapter:"The Justice System" },
  { q:"Which is Canada's highest court?", options:["The Supreme Court of Canada","The Federal Court","The House of Commons","The provincial small claims court"], answer:0, explain:"The Supreme Court of Canada is the final court of appeal for the whole country. It has nine judges.", chapter:"The Justice System" },
  { q:"Why must judges be independent of government?", options:["So they can decide cases fairly, even against the government","So they can make their own laws","So they can choose the Prime Minister","So they never have to explain a decision"], answer:0, explain:"An independent judiciary can rule against the government of the day. That is exactly what protects an ordinary person's rights.", chapter:"The Justice System" },
  { q:"What is the role of the police in Canada?", options:["To keep people safe and enforce the law","To decide guilt and pass sentence","To write the laws","To run the courts"], answer:0, explain:"Police keep people safe and enforce the law. Guilt and sentence are decided by the courts, not by the police.", chapter:"The Justice System" },
  { q:"What should you do if you are stopped by the police in Canada?", options:["Stay calm, be polite and cooperate","Drive away quickly","Refuse to speak at all costs","Offer money"], answer:0, explain:"Stay calm and cooperate. Offering money to a police officer is a serious crime in Canada, not a normal way of solving a problem.", chapter:"The Justice System" },
  { q:"Which national police force serves the whole of Canada?", options:["The Royal Canadian Mounted Police","The Canadian Army","The Coast Guard","The Border Patrol"], answer:0, explain:"The Royal Canadian Mounted Police enforce federal law across Canada, and also serve as the provincial or local police in many places.", chapter:"The Justice System" },
  { q:"Which court usually handles small disagreements about money?", options:["Small claims court","The Supreme Court of Canada","A military court","The Senate"], answer:0, explain:"Small claims court handles disputes over smaller sums, and people often appear without a lawyer.", chapter:"The Justice System" },
  { q:"What is the purpose of a jury in a criminal trial?", options:["Ordinary citizens weigh the evidence and decide the verdict","They choose the judge","They write the charges","They set the law"], answer:0, explain:"A jury of ordinary citizens weighs the evidence and decides the verdict. This is why answering a jury summons matters.", chapter:"The Justice System" },
];
